WITH payload AS (SELECT $archive_payload$[{"id":"d1e0d974-af80-59e0-81fd-a144540fcf21","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -مطالبة الزوجة بالفسخ لوجود تخلف يف عقل الزوج وعدم اإلخبار به قبل الزواج -إنكار الزوج التخلف -تعذر اإلصاح بن الزوجن -االستعانة بأهل اخلبرة (مستشفى الصحة النفسية) -إيجابية التقرير الطبي للزوجة -فسخ النكاح بغير عوض .","document_number":"33370559","case_number":"32273526","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/6","year":"1434","subject":"فسخ نكاح -مطالبة الزوجة بالفسخ لوجود تخلف يف عقل الزوج وعدم اإلخبار به قبل الزواج -إنكار الزوج التخلف -تعذر اإلصاح بن الزوجن -االستعانة بأهل اخلبرة (مستشفى الصحة النفسية) -إيجابية التقرير الطبي للزوجة -فسخ النكاح بغير عوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1433/8/6 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33370559 :‬‬\n                         ‫َر ْق ُم الدعوى‪32273526 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3414425‬تاريخه‪1434/3/8:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬مطالبــة الزوجــة بالفســخ لوجــود تخلــف يف عقــل الــزوج‬\n      ‫وعــدم اإلخبــار بــه قبــل الــزواج ‪ -‬إنــكار الــزوج التخلــف ‪ -‬تعــذر اإلصــاح‬\n      ‫بــن الزوجــن ‪ -‬االســتعانة بأهــل اخلبرة (مستشــفى الصحة النفســية)‬\n            ‫‪ -‬إيجابيــة التقريــر الطبــي للزوجــة‪ -‬فســخ النــكاح بغيــر عــوض ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم ‪« :‬ال ضــرر وال ضــرار» رواه ابــن ماجــه‬\n             ‫والدارقطنــي وغيرهمــا مســندا‪ ،‬وقــال النــووي ‪ (:‬حديــث حســن)‬\n                                                       ‫‪ .2‬قاعدة ‪ (:‬الضرر يزال )‬\n      ‫‪ .3‬قــال أبــو عبيــد‪( :‬إمنــا يســعه الصلــح يف األمــور املشــكلة أمــا إذا‬\n      ‫اســتنارت احلجــة ألحــد اخلصمــن وتبــن لــه موضــع الظالــم فليــس لــه‬\n      ‫أن يحملهمــا علــى الصلــح ونحــوه قــال عطــاء واستحســنه ابــن املنــذر‬\n      ‫وروى عــن شــريح أنــه مــا أصلــح بــن متحاكمــن إال مــرة واحــدة) ا‪.‬ه ـ‬\n                                                                 ‫املغنــي (‪:)29/14‬‬\n      ‫‪ .4‬مــا قــرره أهــل العلــم أن العيــب بــن الزوجــن الــذي يوجــب اخليــار هــو‬\n      ‫‪ :‬مــا ينفــر عــن االســتمتاع وال يحصــل بــه مقصــود النــكاح مــن الرحم ــة‬\n      ‫وامل ــودة‪ .‬انظــر ‪ :‬االختيــارات الفقهيــة البــن تيميــة (ص ‪ )22‬وزاد امل ــعاد‬\n                                                     ‫البــن القيــم (‪. )183-182/5‬‬\n\n\n\n‫‪251‬‬\n\f‫ادعــت املدعيــة املعــرف بهــا مــن قبــل والدهــا أن املدعــى عليــه تزوجهــا‬\n‫بواليــة والدهــا علــى مهــر قــدره خمســة وعشــرون ألــف ريــال واشــترطت‬\n‫عليــه أن يســكنها يف مســكن مســتقل وأن تواصــل دراســتها‪ ،‬وأنــه‬\n‫دخــل بهــا‪ ،‬وبعــد الــزواج بثالثــة أشــهر بــدأت تشــك يف تصرفاتــه حيــث‬\n‫حــاول قتلهــا بالســكني مرتــن وخنقهــا وضربهــا وع ّنفهــا‪ ،‬ثــم تبــن‬\n‫لهــا أنــه يعانــي مــن تخلــف بســيط بــذكاء (‪ )65‬وعيــوب نطــق وضعــف‬\n‫ســمع‪ ،‬ولــم تكــن تعلــم عــن ذلــك قبــل العقــد وإمنــا كانــت تعلــم أنــه‬\n‫كان ضعيــف الســمع فقــط‪ ،‬وقــررت أنهــا تعتبــر هــذا غشــا منــه وطلبــت‬\n‫احلكــم بفســخ نكاحهــا منــه أو أن يطلقهــا ‪ ،‬بعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة صــادق علــى الــزواج والعقــد‪ ،‬والدخــول علــى الوصــف‬\n‫املذكــور ‪ ،‬وأنكــر أن موكلــه حــاول قتلهــا بالســكني مرتــن وخنقهــا‬\n‫وضربهــا‪ ،‬كمــا صــادق علــى مــا ذكرتــه مــن التخلــف البســيط يف‬\n‫موكلــه وعيــوب النطــق وضعــف الســمع وقــرر أن نســبة عقــل موكلــه‬\n‫(‪ )65‬باملئــة نســبة معقولــة وال تؤثــر يف مــدى إمكانيــات القــدرات‬\n‫العقليــة ملوكلــه أو تقلــل مــن أهميتــه‪ ،‬وقــرر أن املدعيــة كانــت تعلــم‬\n‫بــه قبــل العقــد وأن املــأذون الشــرعي ســألها عــن رضاهــا بذلــك ‪،‬‬\n‫وطلــب رد دعــوى املدعيــة‪ ،‬وإلزامهــا باالنقيــاد لبيــت الزوجيــة ‪ ،‬جــرى‬\n‫االطــاع علــى عقــد النــكاح بــن الطرفــن املتضمــن العقــد للمدعيــة‬\n‫علــى املدعــى عليــه بواليــة والدهــا علــى مهــر قــدره خمســة وعشــرون ألــف‬\n‫ريــال مســلمة وعلــى أن تكمــل دراســتها وعلــى أن يوفــر لهــا ســكنا‬\n‫شــرعيا مســتقال ا‪.‬ه ـ ‪ ،‬جــرت محاولــة اإلصــاح بــن الطرفــن فلــم‬\n\n                                                                                   ‫‪252‬‬\n\f      ‫يصطلحــا ‪،‬متــت الكتابــة ملستشــفى الصحــة النفســية للكشــف علــى‬\n      ‫املدعــى عليــه فــورد اجلــواب إيجابي ـ ًا للمدعيــة ‪ ،‬بعرضــه علــى املدعيــة‬\n      ‫أصــرت علــى طلبهــا ‪ ،‬مت طلــب املدعــى عليــه أصالــة‪ ،‬وبســؤاله عــن‬\n      ‫دعــوى املدعيــة قــرر أن مــا ذكــره موكلــه كلــه صحيــح ‪ ،‬وأنكــر مــا‬\n      ‫تضمنــه التقريــر الطبــي وقــرر أنــه ال زال راغبــا بزوجتــه ويطلــب انقيادها‬\n      ‫لبيــت الطاعــة ‪ ،‬مــن كل مــا ســبق وقولــه صلــى اهلل عليــه وســلم‪« :‬ال‬\n      ‫ضــرر وال ضــرار»‪ ،‬ولقاعــدة ‪ (:‬الضــرر يــزال ) والواجــب شــرعا يف شــأن‬\n      ‫الضــرر إذا كان واقعــا أن يســعى يف إزالتــه ورفعــه ‪ ،‬مــا قــرره أهــل العلــم‬\n      ‫أن العيــب بــن الزوجــن الــذي يوجــب اخليــار هــو مــا ينفــر عــن االســتمتاع‬\n      ‫وال يحصــل بــه مقصــود النــكاح مــن الرحمــة واملــودة ‪ ،‬والتخلــف العقلــي‬\n      ‫الــذي باملدعــى عليــه مــن هــذا النــوع ‪ ،‬لــذا مت احلكــم بفســخ نــكاح‬\n      ‫املدعيــة مــن زوجهــا املدعــى عليــه مجانــا بغيــر عــوض ألن الفرقــة أتــت‬\n      ‫مــن قبلــه ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه قــرر عــدم قناعتــه ‪ ،‬جــرى‬\n      ‫إفهــام املدعــى عليــه أن عليــه مراجعــة األحــوال املدنيــة لتســجيل الواقعــة‬\n      ‫وإنــزال اســم املــرأة مــن دفتــر العائلــة بعــد اكتســاب احلكــم القطعيــة ‪،‬‬\n      ‫قــدم املدعــى عليــه الئحتــه االعتراضيــة ولــم يجــد فيهــا ناظــر القضيــة مــا‬\n      ‫يؤثــر علــى مــا حكــم بــه ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                                        ‫املصادقــة عليــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪32273526‬‬\n\n‫‪253‬‬\n\f‫وتاريــخ ‪1432/07/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32850594‬وتاريــخ‬\n‫‪1432/7/9‬ه ـ ففــي يــوم الثالثــاء ‪1432/11/13‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 11 : 19‬وفيهــا حضــرت (‪ )........‬فلســطينية اجلنســية بوثيقــة‬\n‫مصريــة مســلمة الديانــة مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬املعــرف‬\n‫بهــا مــن قبــل أبيهــا (‪ )........‬فلســطيني اجلنســية مســلم الديانــة مبوجــب‬\n‫رخصــة اإلقامــة رقــم (‪ )........‬كمــا حضــر حلضورهــا (‪ )........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬بصفتــه وكيــا عــن‬\n‫‪ .........‬بصــك الوكالــة ذي الرقــم ‪ 93868‬والتاريــخ ‪1432/11/04‬ه ـ‬\n‫اجللــد ‪ 11131‬الصــادر مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n‫وادعــت األولــى قائلــة إن مــوكل هــذا احلاضــر زوجــي عقــد علــي بتاريــخ‬\n‫‪1431/11/23‬ه ـ تقريبــا بواليــة والــدي علــى مهــر وقــدره (‪)25000‬‬\n‫خمســة وعشــرون ألــف ريــال وعلــى أن يســكنني يف مســكن مســتقل‬\n‫وأن أواصــل دراســتي ودخــل بــي بتاريــخ ‪1432/03/13‬ه ـ وبعــد زواجــي‬\n‫بثالثــة أشــهر بــدأت أشــك يف تصرفاتــه فهــو قــد حــاول قتلــي بالســكني‬\n‫مرتــن وخنقنــي باملخــدة وضربنــي وعنفنــي ثــم تبــن لــي أنــه يعانــي مــن‬\n‫تخلــف بســيط بــذكاء ‪ 65‬وعيــوب نطــق وضعــف ســمع ولــم أكــن أعلــم‬\n‫عــن ذلــك قبــل العقــد وكنــت أعلــم أنــه كان ضعيــف الســمع فقــط‬\n‫وذلــك بســبب حادثــة غــرق لــه وهــو صغيــر وهــذا أعتبــره غشــا منــه أطلــب‬\n‫احلكــم لــي بفســخ نكاحــي منــه أو أن يطلقنــي هكــذا ادعــت وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا مــا ذكرتــه املدعيــة مــن‬\n‫زواج موكلــي بهــا وعقــده عليهــا ودخولــه بهــا علــى الوصــف املذكــور‬\n‫فهــو صحيــح ومــا ذكرتــه مــن أنــه حــاول قتلهــا بالســكني مرتــن‬\n‫وخنقهــا وضربهــا ليــس صحيحــا ومــا ذكرتــه مــن نســبة عقــل موكلــي‬\n\n\n                                                                                   ‫‪254‬‬\n\f      ‫‪ 65‬باملئــة فهــي نســبة معقولــة وال تؤثــر يف مــدى إمكانيــات القــدرات‬\n      ‫العقليــة ملوكلــي أو تقلــل مــن أهميتــه ومــا ذكرتــه مــن التخلــف البســيط‬\n      ‫يف موكلــي وعيــوب النطــق وضعــف الســمع فهــو صحيــح وكانــت‬\n      ‫تعلــم بــه قبــل العقــد وقــد ســألها املــأذون الشــرعي عــن رضاهــا بذلــك‬\n      ‫فموكلــي لــم يغشــها أطلــب احلكــم ملوكلــي بــرد الدعــوى وأن تنقــاد‬\n      ‫املدعيــة لبيــت الزوجيــة هكــذا أجــاب وبســؤال املدعــى عليــه وكالــة‬\n      ‫عــن وثيقــة عقــد النــكاح أجــاب قائــا هــي لــدى موكلــي وســأحضرها‬\n      ‫يف اجللســة القادمــة بــإذن اهلل هكــذا أجــاب والنتهــاء وقــت اجللســة‬\n      ‫رفعــت اجللســة ثــم يف يــوم االثنــن ‪1433/02/08‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 08 : 30‬وفيهــا حضــرت ‪ .........‬املثبتــة هويتهــا ســابقا املعــرف‬\n      ‫بهــا مــن قبــل أبيهــا ‪ .........‬املثبتــة هويتــه ســابقا كمــا حضــر حلضورهــا‬\n      ‫‪ .........‬املثبتــة هويتــه ووكالتــه ســابقا وبســؤال املدعــى عليــه وكالــة عــن‬\n      ‫وثيقــة عقــد النــكاح أجــاب قائــا قــد أحضرتهــا معــي هكــذا أجــاب‬\n      ‫وبعــد االطــاع علــى وثيقــة عقــد النــكاح وجدتهــا حتمــل الرقــم ……‬\n      ‫والتاريــخ ‪1431/11/17‬ه ـ وهــي صــادر مــن احملكمــة اجلزئيــة للضمــان‬\n      ‫واألنكحــة مبحافظــة جــدة وتتضمــن العقــد للمدعيــة علــى املدعــى عليه‬\n      ‫بواليــة والدهــا علــى مهــر وقــدره (‪ )25000‬خمســة وعشــرون ألــف ريــال‬\n      ‫مســلمة وعلــى أن تكمــل دراســتها وعلــى أن يوفــر لهــا ســكنا شــرعيا‬\n      ‫مســتقال ا‪.‬ه ـ وقــد حاولــت اإلصــاح بينهمــا فلــم يصطلحــا لــذا قــررت‬\n      ‫الكتابــة ملستشــفى الصحــة النفســية للكشــف علــى املدعــى عليــه‬\n      ‫وإفادتنــا بذلــك‪ ،‬ورفعــت اجللســة حتــى ورود اجلــواب ثــم يف يــوم الســبت‬\n      ‫‪1433/07/12‬ه ـ افتتحــت اجللســة يف الســاعة احلاديــة عشــر والنصــف‬\n      ‫وفيهــا حضــرت املدعيــة أصالــة ‪ ........‬املثبتــة هويتهــا ســابقا املعــرف‬\n\n\n‫‪255‬‬\n\f‫بهــا مــن قبــل أبيهــا ‪ ......‬املثبتــة هويتــه ســابقا كمــا حضــر حلضورهــا‬\n‫‪ .......‬املثبتــة هويتــه ســابقا وقــد جــرت الكتابــة منــا ملستشــفى الصحــة‬\n‫النفســية مبحافظــة جــدة باخلطــاب ذي الرقــم ‪ 33/286330‬والتاريــخ‬\n‫‪1433/02/15‬ه ـ للكشــف علــى ‪ ........‬واإلفــادة عــن ‪ -1‬مــدى قدرتــه‬\n‫العقليــة‪ ،‬وهــل لديــه تخلــف عقلــي ومــا نســبته ‪ -2‬إذا كان لديــه فهــل‬\n‫يضــر غيــره ممــن يقيمــون معــه؟ ‪ -3‬إذا كان لديــه تخلــف عقلــي‪ ،‬فهــل‬\n‫يحســن التصــرف يف مالــه؟ فوردنــا اجلــواب منهــم باخلطــاب رقــم ‪/149‬ل‬\n‫وتاريــخ ‪1433/04/06‬ه ـ املقيــد يف احملكمــة العامــة مبحافظــة جــدة‬\n‫برقــم ‪ 33/688038‬وتاريــخ ‪1433/4/12‬ه ـ واملتضمــن (اجتمعت اللجنة‬\n‫الطبيــة احملليــة لدينــا بتاريــخ ‪1433/02/09‬ه ـ واطلعــت علــى خطــاب‬\n‫فضيلتكــم رقــم ‪ ... 33/286330‬لــه تابع بتاريخ ‪1433/2/2‬هـ ومبعاينة‬\n‫حالــة املذكــور أعــاه وباالطــاع علــى ملفه الطبــي والفحوصات الطبية‬\n‫والنفســية والتقاريــر الصــادرة بحقــه تقــرر مــا يلــي‪ :‬أن املذكــور يعانــي‬\n‫مــن ضعــف يف القــدرات العقليــة مــع ضعــف يف الســمع وبعــد إجــراء‬\n‫اختبــار الــذكاء حتصــل علــى درجــة تصنفــه يف فئــة الــذكاء احلــدي‬\n‫البينــي ( أقــل مــن الطبيعــي ) ولــم يتبــن لنــا أن لديــه ميــا إلحلــاق الضــرر‬\n‫ملــن يقيمــون معــه‪ ،‬وتبــن لنــا كذلــك أنــه يســتطيع التصــرف يف مالــه‬\n‫يف احلــدود البســيطة األخصائــي املعالــج د‪ ............. /‬توقيعــه استشــاري‬\n‫الطــب النفســي د‪ ........... /‬توقيعــه وختمــه استشــاري الطــب النفســي‬\n‫د‪ ......... /‬توقيعــه ســكرتير اللجنــة أ‪ ......... /‬توقيعــه مديــر مستشــفى‬\n‫الصحــة النفســية بجــدة ورئيــس اللجنــة الطبيــة د‪ .............. /‬توقيعــه)‬\n‫ا‪.‬ه ـ نقــل نصــا بأخطائــه اإلمالئيــة وبعرضــه علــى املدعيــة أجابــت قائلــة‬\n‫أنــا مــا زلــت علــى طلبــي الســابق هكــذا أجابــت وقــد طلبــت مــن املدعــى‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫عليــه وكالــة إحضــار موكلــه اجللســة القادمــة فتفهــم ذلــك ورفعــت‬\n      ‫اجللســة مــن أجــل ذلــك ثــم يف يــوم الثالثــاء ‪1433/07/29‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة الواحــدة والنصــف وفيهــا حضــرت ‪ ...........‬املثبتــة‬\n      ‫هويتــه ســابقا املعــرف بهــا مــن قبــل أبيهــا ‪ ........‬املثبتــة هويتــه ســابقا‬\n      ‫كما حضر حلضوره ‪ ..............‬ســعودي اجلنســية مبوجب الســجل املدني‬\n      ‫رقــم ‪ ................‬وبســؤال املدعــى عليــه هــذا احلاضــر عــن دعــوى املدعيــة‬\n      ‫أجــاب قائــا مــا ذكــره موكلــي ســابقا كلــه صحيــح إال مــا ذكــر‬\n      ‫أن عنــدي ضعفــا يف القــدرات العقليــة فغيــر صحيــح فليــس لــدي ذلــك‬\n      ‫هكــذا أجــاب وبســؤاله هــل أخبرهــا مبــا ذكرتــه مــن عيــوب قبــل عقــد‬\n      ‫نكاحــه عليهــا أجــاب قائــا قــد أخبرناهــا بــأن بــي عيوبــا يف النطــق‬\n      ‫والســمع وأمــا العقــل فلــم نخبرهــا ألن عقلــي ليــس بــه ضعفــا هكــذا‬\n      ‫أجــاب وبعــرض التقريــر املرصــود نصــه أعــاه عليــه أجــاب قائــا فــا‬\n      ‫أعلــم أن بــي إال عيبــا يف النطــق والســمع ومــا زلــت راغبــا بزوجتــي‬\n      ‫وأطلــب انقيادهــا لبيــت الطاعــة كمــا أن املستشــفى لــم يخبرونــي أن‬\n      ‫بــي عيبــا إال يف الســمع والنطــق هكــذا أجــاب والنتهــاء وقــت اجللســة‬\n      ‫رفعــت اجللســة ثــم يف يــوم االثنــن ‪1433/08/05‬ه ـ افتتحــت اجللســة يف‬\n      ‫الســاعة احلاديــة عشــر وخمــس وأربعــن دقيقــة وفيهــا حضــرت ‪..........‬‬\n      ‫املثبتــة هويتــه ســابقا املعــرف بهــا مــن قبــل أبيهــا ‪ ..........‬املثبتــة هويتــه‬\n      ‫ســابقا كمــا حضــر حلضورهــا ‪ .........‬املثبتــة هويتــه ســابقا كمــا حضــر‬\n      ‫وكيــل املدعــى عليــه ‪ .......‬املثبتــة هويتــه ووكالتــه ســابقا وقــد قــررت‬\n      ‫املدعيــة قائلــة إنــه قــد أوصلنــي إلــى بيــت أهلــي مــن جمــادى األولــى‬\n      ‫عــام ‪1432‬ه ـ ولــم يســأل عنــي ولــم ألتــق بــه إال يف اجللســة املاضيــة علمــا‬\n      ‫بأنــي مــن ذوات األقــراء وإنــي غيــر راغبــة بــه هكــذا قــررت وبســؤال‬\n\n\n‫‪257‬‬\n\f‫املدعــى عليــه أجــاب قائــا إن كانــت ال ترغــب بــي فأريــد منهــا أن تعيــد‬\n‫مهــري إلــي هكــذا أجــاب‪ ،‬فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة‬\n‫املتضمنــة طلبهــا فســخ نكاحهــا مــن زوجهــا ألنــه لــم يخبرهــا قبــل العقــد‬\n‫بالتخلــف العقلــي الــذي لديــه وإمنــا أخبرهــا بعيــب الســمع والنطــق فقــط‬\n‫قبــل العقــد وأن هــذا يعتبــر غشــا منــه لهــا وبنــاء علــى مــا جــاء يف إجابــة‬\n‫املدعــى عليــه أصالــة أن ليــس بــه إال عيبــان وهمــا يف النطــق والســمع‬\n‫وأمــا العقــل فليــس بــه أي شــيء وبنــاء علــى تقريــر مستشــفى الصحــة‬\n‫النفســية املذكــور أعــاه واملرصــود نصــه أعــاه واملتضمــن أن الــذكاء‬\n‫لــدى املدعــى عليــه أقــل مــن الطبيعــي وأنــه يســتطيع التصــرف يف مالــه‬\n‫يف احلــدود البســيطة ممــا يعنــي أن لديــه تخلفــا ومــع ذلــك فهــو يســتطيع‬\n‫أن يفهــم ســائله وبنــاء علــى ســؤالي لــه وإجابتــه وأنــه أقــر أنــه لــم يخبرهــا‬\n‫بــأن لديــه تخلفــا يف العقــل ولقولــه صلــى اهلل عليــه وســلم ‪ (:‬ال ضــرر وال‬\n‫ضــرار ) رواه ابــن ماجــه والدارقطنــي وغيرهمــا مســندا‪ ،‬وقــال النــووي‬\n‫‪ (:‬حديــث حســن) وقــد أجمــع العلمــاء علــى العمــل بهــذا احلديــث وقــد‬\n‫وقــع الضــرر علــى املدعــى عليهــا وقــد ذكــر بعــض العلمــاء أن نصــف‬\n‫الفقــه ينــدرج حتــت هــذه القاعــدة ووجهــه أن أحــكام الشــرع ال تخلــوا‬\n‫إمــا أن تكــون جللــب املنافــع أو لدفــع املضــار ولقاعــدة ‪ (:‬الضــرر يــزال )‬\n‫وأن الواجــب شــرعا يف شــأن الضــرر إذا كان واقعــا أن يســعى يف إزالتــه‬\n‫ورفعــه ألن الضــرر ظلــم وغــدر والواجــب عــدم إيقاعــه وإقــرار الظالــم‬\n‫علــى ظلمــه حــرام وممنــوع أيضــا فتجــب إزالتــه وملــا قــرره أهــل العلــم أن‬\n‫العيــب بــن الزوجــن الــذي يوجــب اخليــار هــو مــا ينفــر عــن االســتمتاع وال‬\n‫يحصــل بــه مقصــود النــكاح مــن الرحمــة واملــودة ( ينظــر االختيــارات‬\n‫الفقهيــة البــن تيميــة ص ‪ 22‬وزاد املعــاد ‪ ...‬لــه تابــع البــن القيــم ج ‪،5‬‬\n\n\n                                                                                          ‫‪258‬‬\n\f      ‫ص ‪ )183 ،182‬والتخلــف العقلــي الــذي باملدعــى عليــه مــن هــذا النــوع‬\n      ‫وعليــه فقــد فســخت نــكاح املدعــى عليهــا ‪ ...........‬فلســطينية بوثيقــة‬\n      ‫مصريــة مســلمة الديانــة مبوجــب رخصــة اإلقامــة رقــم ……مــن املدعــي‬\n      ‫‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬مجانــا‬\n      ‫بغيــر عــوض ألن الفرقــة أتــت مــن قبلــه وبــه حكمــت وبإعــان احلكــم‬\n      ‫اعتــرض املدعــى عليــه وطلــب التمييــز واســتعد بتقــدمي الئحــة اعتراضيــة‬\n      ‫فأفهــم بــأن عليــه مراجعــة احملكمــة يــوم األربعــاء ‪1433/08/07‬ه ـ‬\n      ‫الســتالم نســخة احلكــم وإذا فــات علــى ميعــاد االعتــراض ثالثــون يومــا‬\n      ‫ولــم يقــدم الئحتــه االعتراضيــة ســقط حقــه يف االعتــراض واكتســب‬\n      ‫احلكــم القطعيــة وأفهمــت املدعيــة أن عليهــا العــدة ثالثــة قــروء تبــدأ‬\n      ‫مــن تاريــخ اليــوم كمــا أفهمــت املدعيــة أنهــا قــد بانــت منــه بينونــة‬\n      ‫صغــرى فــا حتــل لــه إال بعقــد جديــد ومهــر جديــد كمــا أفهمتهــا أال‬\n      ‫تتــزوج حتــى تنتهــي عدتهــا ويكتســب احلكــم القطعيــة كمــا أفهمــت‬\n      ‫املدعــى عليــه بــأن عليــه مراجعــة األحــوال املدنيــة لتســجيل املواقعــة‬\n      ‫وإنــزال اســم املــرأة مــن دفتــر العائلــة بعــد اكتســاب احلكــم القطعيــة‬\n      ‫كمــا قــررت التهميــش علــى وثيقــة عقــد النــكاح بذلــك بعــد اكتســاب‬\n      ‫احلكــم القطعيــة‪ ،‬واختتمــت اجللســة يف الســاعة الثانيــة عشــر‪ ،‬وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                ‫يف‪1433/08/05‬ه ـ‬\n      ‫احلمــد هلل وحــده بعــد فلــدي أنــا فضيلــة الشــيخ ‪ .............‬القاضــي يف‬\n      ‫احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل القاضــي فضيلة الشــيخ‬\n      ‫‪ ...........‬خــال إجازتــه االعتياديــة ففــي يــوم الســبت ‪1433/08/10‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة احلاديــة عشــر والنصــف وفيهــا حضر املدعى‬\n\n\n‫‪259‬‬\n\f‫عليــه وكالــة ‪ ............‬املثبتــة هويتــه ووكالتــه ســابقا واســتلم نســخة‬\n‫احلكــم وأفهــم بتعليمــات التمييــز كمــا يف اجللســة املاضيــة فتفهــم‬\n‫ذلــك واختتمــت اجللســة ثــم يف يــوم الســبت ‪1433/09/09‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الثانيــة والنصــف وفيهــا حضــر املدعــى عليــه وكالــة‬\n‫‪ ........‬املثبتــة هويتــه ووكالتــه ســابقا وقــدم الئحتــه االعتراضيــة املقيــدة‬\n‫يف احملكمــة برقــم ‪ 33167249‬وتاريــخ ‪1433/09/09‬ه ـ واملكونــة‬\n‫مــن ســبع ورقــات‪ ،‬ورفعــت اجللســة لدراســتها ثــم يف يــوم األربعــاء‬\n‫املوافق‪1433/09/13‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة عشــر‬\n‫وقــد مت االطــاع علــى الالئحــة االعتراضيــة ولــم أجــد بهــا مــا يؤثــر مبــا‬\n‫حكمــت بــه لــذا قــررت رفعهــا مــع الصــك وكامــل املعاملــة حملكمــة‬\n‫االســتئناف‪ ،‬واختتمــت اجللســة يف الســاعة الثانيــة عشــر والربــع‪ ،‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪1433/09/13‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ففــي يــوم الســبت ‪1433/12/25‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة احلاديــة عشــرة والربــع وقــد عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف بالرقــم املقيــد يف احملكمــة ‪332068527‬‬\n‫وتاريــخ ‪1433/11/21‬ه ـ وبرفقهــا خطــاب فضيلــة رئيــس محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف ذو الرقــم ‪331806497‬‬\n‫والتاريــخ ‪1433/11/14‬ه ـ واملتضمــن‪ (:‬نفيدكــم أنــه جــرى تدقيــق‬\n‫احلكــم مــن الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال وصــدر بشــأنه القــرار ذو الرقــم ‪33447037‬‬\n‫وتاريــخ ‪1433/11/08‬هــ‪ ،‬نبعثــه لكــم مــع كامــل مشــفوعات املعاملــة‬\n‫إلكمــال الــازم واهلل يحفظكم‪).‬ا‪.‬ه ـ كما برفقها قرار مالحظة رقم‬\n\n\n                                                                                      ‫‪260‬‬\n\f      ‫‪ 33447037‬وتاريخ ‪1433/11/08‬هـ ونصه‪ (:‬احلمد هلل وحده والصالة‬\n      ‫والســام علــى رســول اهلل‪ ،‬وبعــد‪ :‬نحــن قضــاة الدائــرة األولــى لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة‬\n      ‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫جــدة املســاعد رقــم ‪ 32850594‬وتاريــخ ‪1433/10/11‬ه ـ املشــتملة علــى‬\n      ‫الصــك الصــادر مــن فضيلــة الشــيخ ‪ ............‬القاضــي باحملكمــة العامــة‬\n      ‫مبحافظــة جــدة املــؤرخ يف ‪1433/08/06‬ه ـ واملســجل بعــدد ‪33370559‬‬\n      ‫املتضمــن دعــوى ‪ ........‬فلســطينية اجلنســية ضــد ‪ ............‬يف فســخ نــكاح‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n                                            ‫لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪:‬‬\n      ‫‪ -1‬يف الئحــة الدعــوى املقدمــة مــن املدعيــة وأقوالها يف املجلس الشــرعي‬\n      ‫مــا يســتدعي التحقــق مــن علمهــا بحــال املدعــى عليــه ورضاهــا وقبولهــا‬\n                                                             ‫بــه ولــم يتــم النظــر يف ذلــك‪.‬‬\n      ‫‪ -2‬لــم يظهــر مــا مينــع مــن إحالــة الزوجــن إلــى جلنــة اإلصــاح لعلــه يتــم‬\n      ‫االتفــاق علــى رجــوع الزوجــة أو املخالعــة باتفــاق الزوجــن كمــا ميكــن‬\n      ‫اختيــار حكمــن مــن أهلهمــا احتياطــا لفســخ النــكاح مــن ذلــك الــزوج‬\n                                                       ‫واحلــال مــا جــرى اإلشــارة إليــه‪.‬‬\n      ‫‪ -3‬جاء يف الالئحة االعتراضية ما يســتدعي النظر الشــرعي واملناقشــة‬\n      ‫ومــن ذلــك مــا ورد يف الفقــرات الثانيــة والثالثــة واخلامســة مــن الالئحــة‪.‬‬\n      ‫‪ -4‬يف الصفحــة الرابعــة مــن صــك احلكــم مــا يوهــم بــأن اجلــواب علــى‬\n      ‫الالئحــة مــن فضيلــة القائــم بعمــل حاكــم القضيــة وينبغــي التصريــح يف‬\n      ‫الصــك بــأن اجلــواب مــن فضيلــة حاكــم القضيــة كمــا هــو واضــح مــن‬\n\n\n‫‪261‬‬\n\f‫ضبطــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ ،‬قاضــي اســتئناف ‪ ...........‬توقيعــه وختمــه قاضــي اســتئناف‬\n‫‪ ...........‬توقيعــه وختمــه رئيــس الدائــرة ‪ .............‬توقيعــه وختمــه) ا‪.‬ه ـ‬\n‫وأجيــب عمــا ذكــره أصحــاب الفضيلــة وفقهــم اهلل مبــا يلــي‪ :‬أوال‪:‬‬\n‫بالنســبة ملــا ورد يف الفقــرة األولــى مــن قــرار املالحظــة‪ :‬بالرجــوع إلــى‬\n‫ضبــط الدعــوى وجــد أن املــرأة قــد ذكــرت أنهــا ال تعلــم عــن تخلفــه‬\n‫العقلــي كمــا يف ضبــط اجللســة الثانيــة وهــو واضــح كمــا أن املدعــى‬\n‫عليــه قــد ذكــر ذلــك يف معــرض إجابتــه ملــا قــال أنــه لــم يخبــر املدعيــة‬\n‫بذلــك إلنــكاره أن بــه تخلفــا عقليــا‪ .‬ثانيــا‪ :‬بالنســبة ملــا ذكــر يف الفقــرة‬\n‫الثانيــة مــن قــرار املالحظــة‪ :‬بــأن أهــل العلــم قــد ذكــروا مبــا جــاء يف‬\n‫املغنــي البــن قدامــة (‪( :)29/14‬قــال أبــو عبيــد إمنــا يســعه الصلــح يف‬\n‫األمــور املشــكلة أمــا إذا اســتنارت احلجــة ألحــد اخلصمــن وتبــن لــه‬\n‫موضــع الظالــم فليــس لــه أن يحملهمــا علــى الصلــح ونحــوه قــال عطــاء‬\n‫واستحســنه ابــن املنــذر وروى عــن شــريح أنــه مــا أصلــح بــن متحاكمــن‬\n‫إال مــرة واحــدة) ا‪.‬ه ـ ومــا دام أن املدعــي يقــر بذلــك فللمــرأة املدعيــة حــق‬\n‫بالفســخ ثالثــا‪ :‬أمــا اإلجابــة علــى الالئحــة االعتراضيــة فلــم يكــن مــن‬\n‫طــرف القاضــي القائــم بالعمــل وإمنــا مــن طــرف القاضــي ناظــر القضيــة‬\n‫وأمــا بالنســبة لباقــي املالحظــات فلــم يظهــر لــي ســوى مــا حكمــت بــه‬\n‫وعليــه قــررت إعــادة املعاملــة حملكمــة االســتئناف بعــد إحلــاق مــا اســتجد‬\n‫علــى الضبــط والصــك والســجل‪ ،‬واختتمــت اجللســة يف الســاعة احلاديــة‬\n‫عشــرة وخمــس وأربعــن دقيقــة‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/12/25‬ه ـ احلمــد هلل وحــده‬\n‫والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن قضــاة الدائــرة‬\n\n\n                                                                                       ‫‪262‬‬\n\f      ‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى الصــك رقــم ‪ 33370559‬وتاريــخ ‪1433/8/6‬ه ـ الصادر من فضيلة‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جــدة الشــيخ‪ .......... /‬املتضمــن‬\n      ‫‪ ........‬فلســطينية اجلنســية ضــد‪ ..........‬يف فســخ نــكاح وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا‬\n                                               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪263‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":251,"source_page_end":263,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3c2a95cbbbd3b62533279b8d957995bcceabb9adbcda6c5bacc401b3f28306d7","normalized_text_hash":"db8809052cfa9a063cfacbf0186c8c7e21adaf9d060cea837cbeabf6f61b1c41","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p251-33370559"},{"id":"ab6faf3b-ec24-5817-9a7a-6ef40edf5014","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب فسخ النكاح لسوء العشرة وكثرة الشك والضرب وعدم النفقة -بعث حكمن لتقرير األصلح حلال الزوجني -تعديل طلب املدعية أثناء الترافع عما وارد بصحيفة الدعوى -من وجب عليه شيء فامتنع من أداءه استوفاه عنه احلاكم -فسخ النكاح مقابل التنازل عن املهر .","document_number":"33412454","case_number":"32354150","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/16","year":"1434","subject":"فسخ نكاح -طلب فسخ النكاح لسوء العشرة وكثرة الشك والضرب وعدم النفقة -بعث حكمن لتقرير األصلح حلال الزوجني -تعديل طلب املدعية أثناء الترافع عما وارد بصحيفة الدعوى -من وجب عليه شيء فامتنع من أداءه استوفاه عنه احلاكم -فسخ النكاح مقابل التنازل عن املهر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/9/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33412454 :‬‬\n                   ‫َر ْق ُم الدعوى‪32354150 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3418817‬تاريخه‪1434/1/21:‬هـ‬\n\n\n‫فســخ نكاح ‪ -‬طلب فســخ النكاح لســوء العشــرة وكثرة الشك والضرب‬\n‫وعــدم النفقــة ‪ -‬بعــث حكمــن لتقريــر األصلــح حلــال الزوجني ‪ -‬تعديل‬\n‫طلــب املدعيــة أثنــاء الترافــع عمــا وارد بصحيفــة الدعــوى ‪ -‬مــن وجــب‬\n‫عليــه شــيء فامتنــع مــن أداءه اســتوفاه عنــه احلاكــم ‪ -‬فســخ النــكاح‬\n                                              ‫مقابــل التنــازل عــن املهــر ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ( وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n                                                            ‫وحكمــا مــن أهلهــا)‬\n                        ‫‪ -2‬قوله تعالى ( وال تضاروهن لتضيقوا عليهن )‬\n‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ( أميــا امــرأة طلبــت الطــاق مــن غيــر‬\n                                     ‫مــا بــأس فحــرام عليهــا رائحــة اجلنــة )‬\n‫‪ -4‬قولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس مــع امرأتــه خــذ‬\n                                   ‫احلديقــة وطلقهــا تطليقه ‪.‬رواه البخاري‬\n                          ‫‪ -5‬قوله صلى اهلل عليه وسلم ال ضرر وال ضرار‬\n                                          ‫‪ -6‬قاعدة‪ :‬األصل يف األمر الوجوب‬\n‫‪ -7‬قاعــدة‪ :‬مــن وجــب عليــه شــيء فامتنــع مــن أدائــه اســتوفاه عنــه‬\n                                                                     ‫احلاكــم ‪.‬‬\n\n\n\n                                                                                    ‫‪264‬‬\n\f      ‫ادعــت املدعيــة ( بواســطة مترجــم احملكمــة ) بــأن املدعــى عليــه عقــد‬\n      ‫عليهــا ودخــل بهــا الدخــول الشــرعي ولــم يســلمها املهــر املســمى وقــد‬\n      ‫أســاء عشــرتها بالضــرب وكذلــك زوجتــه األخــرى وأوالده منهــا وعــدم‬\n      ‫النفقــة ‪ ،‬طلبــت املدعيــة فســخ نكاحهــا منــه وقــررت عدولهــا عــن طلبها‬\n      ‫الــوارد يف صحيفــة الدعــوى مــن النفقــة وإحســان العشــرة ‪ ،‬صــادق‬\n      ‫املدعــى عليــه علــى الــزواج والصــداق وقــدره وعــدم تســليمه وأنكــر‬\n      ‫إســاءة العشــرة والضــرب مــن قبلــه أومــن قبــل زوجتــه األخــرى وأوالده‬\n      ‫منهــا وقــرر بأنــه لــن يطلــق املدعيــة وطلــب احلكــم عليهــا بالعــودة لبيــت‬\n      ‫الزوجيــة ‪ ،‬جــرى تذكيــر الزوجــة بقــول النبــي صلــى اهلل عليــه وســلم(‬\n      ‫أميــا امــرأة طلبــت الطــاق مــن غيــر مــا بــأس فحــرام عليهــا رائحــة اجلنــة )‬\n      ‫فأصــرت علــى طلــب الطــاق ‪ ،‬اســتجابة لقــول اهلل تعالــى ( فــإن خفتــم‬\n      ‫شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا ) جــرى‬\n      ‫بعــث املعاملــة لقســم اخلبــراء بنــاء علــى طلــب الطرفــن إلجــراء التحكيم‬\n      ‫‪ ،‬ورد القــرار املتضمــن التفريــق بينهمــا هــو املتعــن مقابــل تنــازل الزوجــة‬\n      ‫عــن املهــر ‪ ،‬قــررت املدعيــة تنازلهــا عــن املهــر مقابــل فســخ نكاحهــا‬\n      ‫مــن املدعــى عليــه ‪ ،‬رفــض املدعــى عليــه الطــاق وكذلــك اخللــع الــوارد‬\n      ‫يف قــرار احلكمــن ‪ ،‬لقولــه تعالــى‪ ( :‬وال تضاروهــن لتضيقــوا عليهــن)‬\n      ‫وحلديــث ( ال ضــرر وال ضــرار) ولقولــه صلــى اهلل عليــه وســلم يف قصــة‬\n      ‫ثابــت بــن قيــس مــع امرأتــه خــذ احلديقــة وطلقهــا تطليقــه) رواه البخــاري‬\n      ‫واألصــل يف األمــر الوجــوب وألن مــن وجــب عليــه شــيء فامتنــع مــن أدائــه‬\n      ‫اســتوفاه عنــه احلاكــم لذلــك فقــد صــدر احلكــم بفســخ نــكاح املدعيــة‬\n\n‫‪265‬‬\n\f‫مــن زوجهــا املدعــى عليــه مقابــل تنازلهــا عــن مهرهــا املذكــور وجــرى‬\n‫إفهامهــا بــأن عليهــا العــدة الشــرعية ثالثــة أشــهر ألنهــا مــن اآليســات مــن‬\n‫احليــض بعــد ســؤالها ‪ ،‬قنعــت املدعيــة باحلكــم ولــم يقنــع املدعــى عليــه ‪،‬‬\n                                  ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 32354150‬وتاريــخ ‪ 1432/08/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 321059207‬وتاريــخ ‪ 1432/08/16‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق ‪ 1432/12/26‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n‫(‪ )........‬باكســتانية اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪)........‬‬\n‫املعــرف بهــا مــن قبــل مفتشــة احملكمــة بكتابهــم املرفــق باملعاملــة كما‬\n‫حضــر املترجــم بهــذه احملكمــة (‪ )........‬يحمــل اإلقامــة رقــم (‪)........‬‬\n‫لســماع دعواهــا ضــد (‪ )........‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه‬\n‫ولــم يظهــر تبلغــه بهــذا املوعــد ويف جلســة أخــرى بتاريــخ‪1433/05/04‬‬\n‫ه ـ حضــرت املدعيــة واملعــرف بهــا مــن قبــل أخيهــا (‪ )........‬باكســتاني‬\n‫اجلنســية يحمــل إقامــة رقــم (‪ )........‬كمــا حضــر املدعــى عليــه (‪)........‬‬\n‫باكســتاني اجلنســية يحمــل إقامــة رقــم (‪ )........‬وبســؤال املدعيــة عــن‬\n‫دعواهــا بواســطة مترجــم احملكمــة ‪...‬أجابــت قائلــة إن هــذا احلاضــر‬\n‫معــي زوجــي فقــد عقــد علــي النــكاح بتاريــخ ‪2006/01/10‬م ودخــل‬\n‫بــي الدخــول الشــرعي علــى صــداق وقــدره خمســة وعشــرون ألــف‬\n‫روبيــة باكســتاني لــم أســتلمه وقــد ســاءت عشــرته معــي فهــو يضربنــي‬\n\n                                                                                       ‫‪266‬‬\n\f      ‫وكذلــك زوجتــه الثانيــة وأوالدهــا منــه وال ينفــق علــي أطلــب فســخ‬\n      ‫نكاحــي منــه هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب‬\n      ‫بواســطة املترجــم صحيــح مــا ذكرتــه املدعيــة يف دعواهــا مــن الــزواج‬\n      ‫وتاريخــه والصــداق وقــدره وأنــه لــم تســتلمه أمــا مــا ذكرتــه مــن إســاءة‬\n      ‫العشــرة وضربــي لهــا وكذلــك زوجتــي الثانيــة وأوالدي منهــا فغيــر‬\n      ‫صحيــح وأمــا مــا طلبتــه مــن فســخ النــكاح فأطلــب مهلــة ملــدة عشــرة‬\n      ‫أيــام هكــذا أجــاب ويف جلســة أخــري بتاريــخ ‪ 1433/05/26‬ه ـ وفيهــا‬\n      ‫حضــرت املدعيــة ‪...‬واملعــرف بهــا ‪...‬واملدعــى عليه ‪...‬احلاضرون يف اجللســة‬\n      ‫الســابقة ومترجــم احملكمــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬وقــد قــررت املدعيــة بواســطة املترجــم قائلــة بــأن صحيفــة الدعوى‬\n      ‫قــد طلبــت فيهــا النفقــة وإحســان العشــرة وأنــا قــد عدلــت دعــواي بفســخ‬\n      ‫نكاحــي مــن املدعــى عليــه ولــم نصطلــح علــى شــيء هكــذا قــررت‬\n      ‫وبســؤال املدعــى عليــه بواســطة املترجــم عــن طلــب املدعيــة الطــاق قــال‬\n      ‫لــن أطلقهــا وأطلــب احلكــم عليهــا بالعــودة لبيــت الزوجيــة هكــذا أجــاب‬\n      ‫وقــد جــرى تذكيرهــا بواســطة املترجــم بحديــث الرســول صلــى اهلل‬\n      ‫عليــه وســلم ( أميــا امــرأة طلبــت الطــاق مــن غيــر مــا بــأس فحــرام عليهــا‬\n      ‫رائحــة اجلنــة ) فأصــرت علــى طلــب الطــاق وجــرى عــرض طلبهــا علــى‬\n      ‫املدعى عليه ولعل اهلل أن يكتب لهما خيرا يف طالقه لها فرفض ذلك‬\n      ‫واســتجابة لقــول اهلل تعالــى ( وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا‬\n      ‫مــن أهلــه وحكمــا مــن أهلهــا ) فأمرتهمــا بتحديــد حكمــن فقــاال‬\n      ‫بواســطة املترجــم نحــدد عضويــن مــن احملكمــة كمــا طلبــت املدعيــة‬\n      ‫حضــور أخيهــا املعــرف بهــا ‪...‬وكذلــك طلــب املدعــي حضــور صديقــه ‪...‬‬\n      ‫عنــد احلكمــن حملاولــة الصلــح وأن يقــرر عضــوي احملكمــة احلكمــن‬\n\n\n‫‪267‬‬\n\f‫مــا يريــان مــن جمــع أو فرقــة بعــوض أو بــدون عــوض فأجيــب لطلبهمــا‬\n‫ويف جلســة أخــري بتاريــخ ‪ 1433/07/05‬ه ـ حضــرت املدعيــة ولــم تردنــا‬\n‫إفــادة مــن قســم اخلبــراء لــذا رفعــت اجللســة حتــى ورود اجلــواب ويف جلســة‬\n‫أخــري بتاريــخ ‪ 1433/09/13‬ه ـ حضــرت املدعيــة واملعــرف بهــا مــن قبــل‬\n‫‪...‬كمــا حضــر مترجــم احملكمــة ‪...‬وقــد حضــر املدعــى عليــه متأخــرا‬\n‫عنــد الســاعة الثانيــة والنصــف وقــد وردنــا كتــاب قســم اخلبــراء رقــم‬\n‫‪ 321059207‬وتاريــخ ‪1433/7/14‬ه ـ وبرفقــه القــرار رقــم ‪ 544‬وتاريــخ‬\n‫‪1433/7/14‬ه ـ ونــص احلاجــة منــه ( عليــه نفيد فضيلتــه أنه مت االجتماع‬\n‫بالطرفــن وقــد تعــذر الصلــح بينهمــا حيــث ذكــرت املدعيــة بأنهــا ال‬\n‫ترغــب العيــش مــع زوجهــا املذكــور وذلــك لكونــه ال يقــوم بالنفقــة‬\n‫عليهــا وأنــه كثيــر الشــك بهــا وأن أوالده مــن زوجتــه الثانيــة قــد اعتــدوا‬\n‫عليهــا بالضــرب وأنــه لــم يســلمها املهــر املقــدر بخمســة وعشــرين ألــف‬\n‫روبيــه باكســتاني وأنهــا علــى اســتعداد للتنــازل عنــه مقابــل طالقهــا أمــا‬\n‫بالنســبة للمدعــى عليــه فقــد ذكــر بأنــه ال يرغــب يف طــاق املدعيــة وانه‬\n‫علــى اســتعداد بتســليمها مهرهــا املذكــور وجتــدون إقــرار كل منهمــا‬\n‫بطــي املعاملــة وبنــاء علــى ذلــك وبعــد االجتمــاع بالطرفــن ومناقشــتهما‬\n‫وســماع أقوالهمــا والتأمــل يف حالهمــا ولعــدم الوفــاق بينهمــا فإننــا نــرى‬\n‫أن التفريــق بينهمــا هــو املتعــن مقابــل تنازلهــا عــن املهــر )أ‪.‬ه ـ وبعــرض‬\n‫ذلــك علــى املدعيــة بواســطة املترجــم قائلــة إننــي متنازلــة عــن املهــر وقــدره‬\n‫خمســة وعشــرون ألــف روبيــه باكســتاني مقابــل فســخ نكاحــي مــن‬\n‫املدعــى عليــه هكــذا قــررت فجــرى نصحهــا بالذهــاب لبيــت الزوجيــة‬\n‫فرفضــت ذلــك وقالــت أنــا متضــررة وأطلــب فســخ نكاحي حــاال هكذا‬\n‫أجابــت وبعــرض ذلــك علــى املدعــى عليــه رفــض طالقهــا وكذلــك اخللــع‬\n\n\n                                                                                         ‫‪268‬‬\n\f      ‫الــوارد يف قــرار احلكمــن املرصــود أعــاه هكــذا أجــاب بواســطة‬\n      ‫املترجــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن الزوجــة‬\n      ‫تطلــب فســخ نكاحهــا وقــد أصــرت علــى ذلــك وقــد رفــض الــزوج ذلــك‬\n      ‫وحيــث تنازلــت عــن املهــر وملــا ورد يف قــرار احلكمــن وألن بقائهــا طــول‬\n      ‫هــذه املــدة ناشــزا ضــرر عليهــا ولقولــه تعالــى ( وال تضاروهــن لتضيقــوا‬\n      ‫عليهــن ) وحلديــث( ال ضــرر وال ضــرار ) وقــد شــرع رفــع الضــرر بالفرقــة‬\n      ‫بــن الزوجــن ولقولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس‬\n      ‫مــع امرأتــه ( خــذ احلديقــة وطلقهــا تطليقــة ) رواه البخــاري واألصــل يف‬\n      ‫األمــر الوجــوب كمــا قــرره أهــل العلــم وألن الــزوج امتنــع مــن الطــاق‬\n      ‫وألن مــن وجــب عليــه شــيء وامتنــع أدائــه اســتوفاه عنــه احلاكــم لذلــك‬\n      ‫كلــه فقــد فســخت نــكاح املدعيــة ‪ ......‬مــن زوجهــا املدعــى عليــه‬\n      ‫‪...‬باكســتاني اجلنســية يحمــل إقامــة رقــم ‪...‬مقابــل تنــازل املدعيــة عــن‬\n      ‫مهرهــا املذكــور أعــاه وبذلــك قضيــت وأفهمتهــا بــأن عليهــا العــدة‬\n      ‫الشــرعية لهــذا الفســخ ابتــداء مــن تاريــخ احلكــم وهــي ثالثــة أشــهر فهــي‬\n      ‫مــن اآليســات مــن احليــض بعــد ســؤالها وبعــرض احلكــم علــى املدعيــة‬\n      ‫قنعــت بــه ولــم يقنــع بــه املدعــى عليــه وطلــب متييــزه واســتعد بتقــدمي الئحــة‬\n      ‫اعتراضيــة فأجيــب لطلبــه وأفهــم بــأن عليــه مراجعــة احملكمــة يــوم‬\n      ‫الثالثــاء بتاريــخ ‪1433/09/19‬ه ـ الســتالم نســخة مــن احلكــم وأفهــم‬\n      ‫بأنــه إذا مضــى ثالثــون يومــا مــن موعــد اســتالم نســخة احلكــم ولــم يقدم‬\n      ‫خاللهــا الئحتــه االعتراضيــة فيســقط حقــه يف االعتــراض ويكتســب‬\n      ‫احلكــم القطعيــة كمــا أفهمــت املدعيــة بــأن ال تســتقبل اخلطــاب إال بعد‬\n      ‫اكتســاب احلكــم القطعيــة وانتهــاء العــدة الشــرعية‪ ،‬وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n\n\n‫‪269‬‬\n\f                                                              ‫‪ 1433/09/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/02/17‬ه ـ‬\n‫افتتحــت اجللســة وقــد عــادت املعاملــة مــن محكمة االســتئناف بكتابهم‬\n‫رقــم ‪ 3495952‬وتاريــخ ‪1434/2/5‬ه ـ وبرفقــه القــرار رقــم ‪3418817‬‬\n‫وتاريــخ ‪1434/1/21‬ه ـ الصــادر مــن دائــرة األحــوال الشــخصية الثانيــة‬\n‫ونصــه ( وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ) أ‪.‬ه ـ وكــي ال يخفــى‬\n‫جــرى إثباتــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫املســاعد بالريــاض برقــم ‪ 331059207‬وتاريــخ ‪1434/1/4‬هـ املرفق بها‬\n‫الصــك الصــادر مــن فضيلــة القاضي باحملكمة الشــيخ ‪ ...‬املســجل برقم‬\n‫‪ 33412454‬وتاريــخ ‪1433/9/16‬ه ـ اخلــاص بدعــوى‪ ... /‬باكســتانية‬\n‫اجلنســية ضــد‪ ... /‬باكســتاني اجلنســية بشــأن فســخ نــكاح وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة‬\n‫املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و‬\n                                                     ‫علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪270‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":264,"source_page_end":270,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3878f129bcf39ce3f8ec86ebfbcb6c1dc69da7ee90348814902ab1e8256ff510","normalized_text_hash":"a1ff656a3db01638cf6543851d786f91abdd6b8ae267ee88b5b44cd0567331db","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p264-33412454"},{"id":"4c8d3ab9-5659-5a6a-a708-dc44122fb6d3","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -املطالبة بفسخ نكاح لعدم النفقة والهجر -عدم حضور املدعى عليه رغم تبليغه -شهادة الشاهدين املعدلن بصحة الدعوى -ثبوت الضرر وعدم النفقة -احلكم غيابي ا بفسخ النكاح للضرر وعدم النفقة .","document_number":"33396666","case_number":"32360747","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/28","year":"1434","subject":"فسخ نكاح -املطالبة بفسخ نكاح لعدم النفقة والهجر -عدم حضور املدعى عليه رغم تبليغه -شهادة الشاهدين املعدلن بصحة الدعوى -ثبوت الضرر وعدم النفقة -احلكم غيابي ا بفسخ النكاح للضرر وعدم النفقة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/8/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33396666 :‬‬\n                         ‫َر ْق ُم الدعوى‪32360747 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34313906‬تاريخه‪1434/9/7:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬املطالبــة بفســخ نــكاح لعــدم النفقــة والهجــر ‪ -‬عــدم‬\n      ‫حضــور املدعــى عليــه رغــم تبليغــه ‪ -‬شــهادة الشــاهدين املعدلــن بصحــة‬\n      ‫الدعــوى ‪ -‬ثبــوت الضــرر وعــدم النفقــة ‪ -‬احلكــم غيابيـ ًا بفســخ النــكاح‬\n                                                           ‫للضــرر وعــدم النفقــة ‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قول اهلل تعالى ( فإمساك مبعروف أو تسريح بإحسان )‬\n                    ‫‪ .2‬قول الرسول صلى اهلل عليه وسلم ( ال ضرر وال ضرار )‬\n      ‫‪ .3‬أمــر النبــي صلــى اهلل عليــه وســلم امــرأة ثابــت بــن قيــس ( أن تتربــص‬\n                                  ‫حيضــه واحــدة وتلحــق بأهلهــا ) رواه النســائي‬\n      ‫‪ .4‬قــول ابــن تيميــه رحمــه اهلل ( املختلعــة يكفيهــا االعتــداد بحيضــة‬\n                                                        ‫واحــدة ) االختيــارات ‪282‬‬\n      ‫‪ .5‬قــول ابــن القيــم رحمــه اهلل (وهــي مقتضــى قواعــد الشــريعة فــإن‬\n      ‫العــدة إمنــا جعلــت ثــاث حيــض ليطــول زمــن الرجعــة إلــخ ‪ )...‬زاد‬\n                                                                     ‫املعــاد ‪.199/5‬‬\n      ‫‪ .6‬قــال يف كشــاف القنــاع ( وألن هــذا أولــى بالفســخ مــن العجــز‬\n                                    ‫بالــوطء ) يعنــي الفســخ بتــرك النفقــة‬\n            ‫‪ .7‬املادة رقم ‪ 12‬واملادة ‪ 15‬واملادة ‪ 55‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n‫‪271‬‬\n\f‫أقامــت زوجــة دعــوى علــى زوجهــا الغائــب عــن مجلــس احلكــم تطالبــه‬\n‫معاشــرتها باملعــروف أو إلزامــه بتطليقهــا ‪ ،‬لــم يحضــر املدعــى عليــه‬\n‫‪ ،‬عدلــت املدعيــة دعواهــا وطلبــت فســخ نكاحهــا مــن املدعــى عليــه‬\n‫‪ ،‬لــم يحضــر املدعــى عليــه رغــم تبليغــه مرتــن ‪ ،‬وأحضــرت شــاهدين‬\n‫شــهدا بــأن املدعــى عليــه ال ينفــق علــى زوجتــه وال علــى أوالده منهــا‬\n‫وأنــه تــارك لزوجتــه منــذ ثــاث ســنوات تقريبــا ‪ ،‬وأحــد الشــاهدين مــن‬\n‫أقــارب املدعيــة والثانــي جــار ألهلهــا ‪ ،‬كمــا أحضــرت شــاهدا آخــر‬\n‫شــهد بصحــة دعــوى املدعيــة وجــرى تزكيــة الشــهود ‪ ،‬فبنــاء علــى أن‬\n‫املدعــى عليــه تبلــغ تبليغـ ًا صحيحــا وفقــا للمــادة الثانيــة عشــرة واخلامســة‬\n‫عشــرة مــن نظــام املرافعــات الشــرعية ولــم يحضــر وألن عــدم حضــوره‬\n‫إضــرار باملدعيــة والضــرر يــزال لقولــه صلــى اهلل عليــه وســلم ( ال ضــرر‬\n‫وال ضــرار ) ولشــهادة الشــاهدين ولقولــه تعالــى ( فإمســاك مبعــروف‬\n‫أو تســريح بإحســان) وألن مــن وجــب عليــه شــيء وامتنــع عــن أدائــه أداه‬\n‫احلاكــم عنــه فســخت احملكمــة نــكاح املدعيــة مــن املدعــى عليــه مــن‬\n‫غيــر عــوض وبــه قضــت واعتبــرت هــذا احلكــم غيابي ـ ًا للمدعــى عليــه‬\n‫وأفهمــت املدعيــة أن عليهــا العــدة الشــرعية لهــذا الفســخ وهــي حيضــة‬\n‫علــى الصحيــح ‪ ،‬رفــع هــذا اإلجــراء حملكمــة االســتئناف وصــدق‬\n                                                                  ‫احلكــم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪272‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمة العامة ‪/‬املساعد وتاريخ ‪1432/08/19‬هـ املقيدة باحملكمة‬\n      ‫برقــم ‪ 321075041‬وتاريــخ ‪1432/08/19‬ه ـ ففــي يــوم األحــد املوافــق‬\n      ‫‪1433/04/25‬ه ـ حضــرت املدعيــة (‪ )........‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي (‪ )........‬ولــم يحضــر املدعــى عليــه (‪ )........‬وقدمــت‬\n      ‫املدعيــة ورقــة تبليــغ محضــري اخلصــوم وتاريــخ ‪1433/3/6‬ه ـ والتبليــغ‬\n      ‫ليــس مختومــا مــن قســم محضــري اخلصــوم وعليــه توقيــع املدعــى عليــه‬\n      ‫حيــث ذكــرت املدعيــة أنــه جــاء إلــى البيــت ووقّ ــع علــى التبليــغ وأنهــا‬\n      ‫ال تعــرف لــه أي عنــوان وأنــه ال يعمــل لــذا جــرى تأجيــل اجللســة إلــى‬\n      ‫‪1433/6/8‬ه ـ لتبليــغ املدعــى عليــه عــن طريــق البحــث والتحــري ويف‬\n      ‫يــوم األحــد املوافــق ‪1433/06/08‬ه ـ حضــرت املدعيــة ‪ ..........‬واملدونــة‬\n      ‫هويتهــا ســابقا ولــم يحضــر املدعــى عليــه ‪ ...........‬وقــد وردنــا خطــاب‬\n      ‫البحــث والتحــري رقــم ‪ 20/10441‬وتاريــخ ‪1433/5/19‬ه ـ وفيــه (بأنــه‬\n      ‫بالرجــوع للحاســب اآللــي طرفنــا اتضــح بــأن عنــوان املذكــور ‪ ......‬املطلع‬\n      ‫بواســطة جــوال رقــم ( ) وبعــرض ذلــك علــى املدعية قالت إن املدعى عليه‬\n      ‫يســكن يف مدينــة وأنــا متأكــدة ولــدي شــهود أنــه يســكن يف مدينــة‬\n      ‫جــدة هكــذا قالــت ويف يــوم االثنــن املوافق‪1433/07/07‬ه ـ حضــرت‬\n      ‫املدعيــة واملدونــة هويتهــا ســابقا وبســؤالها عــن الشــهود أحضــرت‬\n      ‫للشــهادة كال مــن ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫وســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وبســؤال مبفــرده قــال (‬\n\n‫‪273‬‬\n\f‫أشــهد بــاهلل العظيــم أن املدعــى عليــه يســكن يف الوقــت احلالــي يف حــي‬\n‫مبدينــة وأوالده هــم و مــن زوجتــه) هكــذا شــهد وبســؤال مبفــرده قــال‬\n‫( أشــهد بــاهلل العظيــم أنــي أعــرف املدعــى عليــه وأنــا أســكن بجــواره‬\n‫يف حــي مبدينــة وكانــت آخــر مــرة رأيتــه قبــل شــهر ولديــه أوالد هــم و‬\n‫مــن زوجتــه) هكــذا شــهد وبســؤالها عــن املعدلــن للشــهود أحضــرت‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم و مبوجــب اإلقامــة رقــم‬\n‫وبســؤال ‪ .......‬عــن الشــهود قــال أعــرف الشــهود وأقبــل شــهادتهم لــي‬\n‫وعلــي هكــذا قــال وبســؤال عــن الشــهود قــال أعــرف الشــهود وأقبــل‬\n‫شــهادتهم لــي وعلــي هكــذا قــال لــذا قــررت ســماع الدعــوى غيابيــا بنــاء‬\n‫علــى املــادة (‪ )55‬مــن نظــام املرافعات الشــرعية والئحته وبســؤال املدعية‬\n‫عــن دعواهــا قالــت إن املدعــى عليــه هــو زوجــي مبوجــب العقــد الشــرعي‬\n‫الصحيــح ولــي منــه ثالثــة أوالد هــم ‪ .....‬وعمرهــا عشــر ســنوات و‪.....‬‬\n‫وعمــره ثمــان ســنوات و‪ .......‬وعمرهــا أربــع ســنوات وهــو مقصــر معنــا‬\n‫ال يصــرف علينــا وال يســأل عنــا وال يقــوم بإعطائــي حلقوقــي الشــرعية‬\n‫وقــد حاولــت يف االصــاح ولكــن دون جــدوى وأنــا علــى هــذه احلــال مــا‬\n‫يقــارب ســنتان ونصــف اطلــب إمــا إمســاك مبعــروف أو تطليقــي منــه‬\n‫هــذه دعــواي وقدمــت ســجل األســرة الصــادر مــن األحــوال املدنيــة وفيــه‬\n‫اســم الــزوج املدعــى عليــه ‪ ........‬وفيــه اســم الزوجــة املدعيــة واألوالد ‪.....‬‬\n‫و‪ ......‬و‪ ......‬ثــم جــرى تأجيــل اجللســة إلــى ‪1433/8/13‬ه ـ لطلــب املدعــى‬\n‫عليــه مــرة أخــرى عــن طريــق البحــث والتحــري ويف يــوم الثالثــاء املوافــق‬\n‫‪1433/08/27‬ه ـ حضــرت املدعيــة واملدونــة هويتهــا ســابقا ولــم يحضــر‬\n‫املدعــى عليــه وقــد وردنــا خطــاب البحــث والتحــري رقــم ‪13/6477‬‬\n‫وتاريــخ ‪1433/8/18‬ه ـ وفيــه (عليــه نفيدكــم أنــه مت البحــث عــن‬\n\n\n                                                                                        ‫‪274‬‬\n\f      ‫املذكــور ومت احلصــول علــى جوالــه رقــم وباالتصــال عليــه مت افهامــه‬\n      ‫مبوعــد اجللســة املقــررة واســتعد مبراجعتكــم باملوعــد احملــدد ) لــذا‬\n      ‫قــررت الســير يف الدعــوى وبســؤال املدعيــة قالــت أنــا ال أريــد فســخ‬\n          ‫نكاحــي وإمنــا أطلــب معاشــرة زوجــي لــي باملعــروف هكــذا قالــت ‪.‬‬\n      ‫ويف يــوم الســبت املوافــق ‪1433/10/14‬ه ـ حضــرت املدعيــة واملدونــة‬\n      ‫هويتهــا ســابقا ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه ثــم قــررت‬\n      ‫املدعيــة قائلــة اننــي قابلــت املدعــى عليــه يف شــهر رمضــان وطلبــت منــه‬\n      ‫امســاكي مبعــروف أو تســريحي بإحســان فاســتهزأ بــي وأنــا اآلن‬\n      ‫متضــررة مــن بقائــي طيلــة هــذه الفتــرة معلقــة وأطلــب تعديــل دعــواي‬\n      ‫وفســخ نكاحــي مــن املدعــى عليه هكذا قــررت ويف يوم االثنني املوافق‬\n      ‫‪ 1433/10/16‬ه ـ لــدي أنــا القاضــي باحملكمــة العامــة خلــف فضيلــة‬\n      ‫القاضــي افتتحــت اجللســة وفيهــا حضــرت املدعيــة املثبــت حضورهــا يف‬\n      ‫جلســة ســابقة واملعــرف بهــا مــن قبــل الشــاهدين املذكوريــن أدنــاه ثــم‬\n      ‫قــررت املدعيــة قائلــة اننــي يف بيــت مســتقل أنا وأبنائي منذ ثالث ســنوات‬\n      ‫وال ينفــق علينــا وال يجلــس معنــا اطالقــا هكــذا قــررت وبســؤالها علــى‬\n      ‫بينتهــا يف ذلــك أحضــرت للشــهادة وأدائهــا ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة الوطنيــة رقــم وهــو مــن مواليــد عــام ‪1396‬ه ويعمــل يف إدارة ‪.....‬‬\n      ‫بــوزارة ‪ ......‬وهــو زوج ألخــت املدعيــة كمــا افادكمــا أحضــرت ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم وهــو مــن مواليــد عــام ‪1390‬ه ـ وال‬\n      ‫يعمــل وهــو مــن جيــران املدعيــة وبســؤالهما عمــا لديهــا أجــاب كل واحــد‬\n      ‫منهمــا مبفــرده قائــا (أشــهد هلل ان املدعــى عليــه ال ينفــق علــى زوجتــه‬\n      ‫وال علــى ابنائــه وانــه تــارك لزوجتــه منــذ ثــاث ســنوات تقريبــا ) هكــذا‬\n      ‫شــهدا وبســؤالهما عــن كيفيــة حتملهمــا لشــهادتهما أجــاب األول‬\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":271,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12ab9180266d70705023259d66bc7c5c25c58506e5d7410d70ef42e676f499ef","normalized_text_hash":"1622b0a971afad41a6eb7491f1eb386787cb10378ddb36e6c2b207f36e120b9e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p271-33396666"},{"id":"ee7d0a1f-6077-5b0d-863c-596d2f10c517","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول ،لعدم النفقة، وسوء العشرة -إنكار املدعى عليه -تعذر الصلح بن الزوجن -قرر احلكمان الفسخ على نصف املهر -احلكم بفسخ النكاح على نصف","document_number":"33483169","case_number":"32457994","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/29","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول ،لعدم النفقة، وسوء العشرة -إنكار املدعى عليه -تعذر الصلح بن الزوجن -قرر احلكمان الفسخ على نصف املهر -احلكم بفسخ النكاح على نصف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/29 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33483169 :‬‬\n                    ‫َر ْق ُم الدعوى‪32457994 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3457239‬تاريخه‪1434/3/8:‬هـ‬\n\n\n ‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول‪ ،‬لعــدم النفقــة‪،‬‬\n ‫وســوء العشــرة ‪ -‬إنــكار املدعــى عليــه ‪ -‬تعــذر الصلــح بــن الزوجــن ‪ -‬قــرر‬\n ‫احلكمــان الفســخ علــى نصــف املهــر ‪ -‬احلكــم بفســخ النــكاح علــى نصــف‬\n                                                                           ‫املهــر ‪.‬‬\n\n\n\n\n ‫‪ .1‬قولــه تعالــى‪« :‬وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا إن اهلل كان‬\n                                                                ‫عليمــا خبيــرا» ‪.‬‬\n ‫‪ .2‬مــا رواه البخــاري عــن ابــن عبــاس رضــي اهلل عنهمــا قــال جــاءت امــرأة‬\n ‫ثابــت بــن قيــس إلــى النبــي صلــى اهلل عليــه وســلم فقالــت يــا رســول اهلل‬\n ‫مــا أنقــم علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف الكفــر يف اإلســام‬\n ‫فقــال رســول اهلل صلــى اهلل عليــه وســلم أترديــن عليــه حديقتــه قالــت‬\n                                            ‫نعــم فــردت عليــه فأمــره ففارقهــا)‪.‬‬\n                                    ‫‪ .3‬قوله عليه السالم (ال ضرر وال ضرار)‬\n ‫‪ .4‬مــا رواه النســائي وعبــد الــرزاق عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‬\n ‫(بعثــت أنــا ومعاويــة حكمــن قــال معمــر بلغنــي أن عثمــان بعثهمــا وقــال‬\n               ‫إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن تفرقــا ففرقــا)‪.‬‬\n ‫‪ .5‬مــا رواه الــدار قطنــي والنســائي والشــافعي والبيهقــي عــن محمــد‬\n ‫بــن ســيرين عــن عبيــدة قــال جــاء رجــل وامــرأة إلــى علــي مــع كل واحــد‬\n                                                                                       ‫‪282‬‬\n\f      ‫منهمــا فئــام مــن النــاس فأمرهــم فبعثــوا حكمــا مــن أهلــه وحكمــا مــن‬\n      ‫أهلهــا وقــال للحكمــن هــل تدريــا مــا عليكمــا إن رأيتمــا أن جتمعــا‬\n      ‫فاجمعــا وإن رأيتمــا أن تفرقــا فرقتمــا فقالــت املــرأة رضيــت بكتــاب اهلل‬\n      ‫مبــا علــي فيــه ولــي وقــال الــزوج أمــا الفرقــة فــا فقــال علــي كذبــت‬\n      ‫واهلل ال تبــرح حتــى تقــر مثــل الــذي أقــرت بــه) قــال ابــن حجــر إســناده‬\n                                                                            ‫صحيــح ‪.‬‬\n      ‫‪ .6‬مــا أخرجــه الطبــري يف تفســيره عــن ابــن عبــاس رضــي اهلل عنهمــا‬\n      ‫يف احلكمــن أنــه قــال‪ :‬فــإن اجتمــع أمرهمــا علــى أن يفرقــا أو يجمعــا‬\n                                                                   ‫فأمرهمــا جائــز ‪.‬‬\n          ‫‪ .7‬املادة ‪/10/34‬هـ من نظام املرافعات الشرعية‪ ،‬ولوائحه التنفيذية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة املعــرف بهــا مــن قبــل والدهــا علــى املدعــى عليــه الغائــب‬\n      ‫عــن مجلــس احلكــم أنــه تزوجهــا ‪ ،‬ودخــل بهــا‪ ،‬ولــم تنجــب منــه أوالد ًا‬\n      ‫‪ ،‬وأنــه لــم يقــم بتأمــن بيــت الزوجيــة وال ينفــق عليهــا النفقــة الواجبــة‬\n      ‫عليــه‪ ،‬باإلضافــة إلــى أنــه يشــتمها ويضربهــا‪ ،‬ممــا جعــل احليــاة معــه ال‬\n      ‫حتتمــل وال تطــاق وطلبــت احلكــم عليــه بفســخ عقــد نكاحهــا منــه ‪ -‬مت‬\n      ‫االســتخالف لســماع جــواب املدعــى عليــه ‪ ،‬ورد جــواب االســتخالف‬\n      ‫املتضمــن جــواب املدعــى عليــه وكالــة باملصادقــة علــى الــزواج‬\n      ‫والدخــول‪ ،‬وعــدم األوالد‪ ،‬وأنكــر مــا ســوى ذلــك‪ ،‬ودفــع أن املدعيــة‬\n      ‫لــم تبــق يف بيــت موكلــه إال أربعــة أشــهر تقريبــا ثــم ذهبــت لبيــت أهلهــا‬\n      ‫ورفضــت العــودة مــرة أخــرى مــع العلــم أنــه مت تأمــن ســكن لهــا خــاص‬\n      ‫يف احملافظــة التــي يســكن بهــا موكلــه وطلــب مــن املدعيــة الرجــوع‬\n\n‫‪283‬‬\n\f‫لبيتهــا أو إعــادة مــا مت دفعــه لهــا إذا كانــت ال تريــد الرجــوع ‪ ،‬حضــر‬\n‫املدعــى عليــه أصالــة وجــرى تــاوة مــا ســبق رصــده عليــه فصــادق علــى‬\n‫جــواب وكيلــه الشــرعي ‪ ،‬بعــرض ذلــك علــى املدعيــة قــررت أنهــا لســت‬\n‫ا وأنهــا ليــس لديهــا بينــة‬\n                             ‫موافقــة علــى مــا جــاء يف جوابــه جملــة وتفصيـ ً‬\n‫علــى دعواهــا ‪ ،‬جــرى وعــظ الزوجــة والــزوج فأصــرا علــى موقفهمــا ‪-‬‬\n‫بطلــب احلكمــن مــن الطرفــن‪ ،‬قــررا أنــه ليــس هنــاك مــن أهلهمــا مــن‬\n‫هــو أهــل لتولــي التحكيــم ‪ ،‬متــت الكتابــة لهيئــة النظــر للوقــوف علــى‬\n‫حــال املتداعيــن واإلفــادة عــن مرئياتهــا حيالهمــا مــن جمــع أو فرقــه‬\n‫بعــوض أو دونــه ‪ -‬ورد اجلــواب املتضمــن‪ :‬الــذي نــراه التفريــق بينهمــا‬\n‫بعــوض يعــاد لــه نصــف املهــر كــون املذكــور تــرك زوجتــه عنــد أهلهــا‬\n‫ملــدة ثــاث ســنوات دون معاجلــة أ‪.‬ه ـ بعرضــه علــى املتداعيــن قــررت‬\n‫املدعيــة موافقتهــا عليــه بينمــا رفضــه املدعــي عليــه وكالــه ‪ -‬بســؤالهما‬\n‫عــن مقــدار املهــر أجابــا أن عقــد النــكاح تضمــن أن املهــر خمســون‬\n‫ألــف ريــال ‪ ،‬أحضــرت املدعيــة العــوض البالــغ خمســة وعشــرين ألــف‬\n‫ريــال مبوجــب شــيك مصــريف ‪ -‬بعرضــه علــى املدعــى عليــه رفضــه ‪،‬‬\n‫بنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا قررتــه هيئــة النظــر مــن‬\n‫التفريــق بــن املتداعيــن علــى نصــف املهــر ‪ ،‬مــا مت مــن وعــظ الزوجــن‬\n‫وتوجيههمــا وإصــرار كل منهمــا علــى رأيــه ‪ ،‬اســتمرار احليــاة الزوجيــة‬\n‫علــى هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح يف الشــريعة مــن‬\n‫املــودة والرحمــة والســكن والعفــة مــع مــا يف ذلــك مــن املضــار النفســية‬\n‫واالجتماعيــة علــى الزوجــن مــع مــا ينشــأ عــن ذلــك مــن الظلــم واإلثــم‬\n‫والقطيعــة بــن األســر وتوليــد العــداوة والبغضــاء ‪ ،‬لــذا مت احلكم بفســخ‬\n‫نــكاح املدعيــة مــن زوجهــا املدعــى عليــه علــى عــوض قــدره خمســة‬\n\n\n                                                                                      ‫‪284‬‬\n\f      ‫وعشــرون ألــف ريــال ‪ -‬بعــرض ذلــك علــى الطرفــن قــررت املدعيــة‬\n      ‫القناعــة وقــرر املدعــى عليــه عدمهــا وطلــب اســتئناف احلكــم ‪ -‬جــرى‬\n      ‫إفهــام املدعيــة أن عليهــا العــدة الشــرعية اعتبــار ًا مــن تاريــخ احلكــم وأن‬\n      ‫ال تتــزوج حتــى يكتســب احلكــم القطعيــة ‪ -‬جــرى إفهــام املدعــى عليــه‬\n      ‫أن زوجتــه املدعيــة بانــت مــن بينونــة صغــرى ال حتــل لــه إال بعقــد جديــد‪-‬‬\n                 ‫بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32457994‬وتاريــخ‬\n      ‫‪1432/10/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321297262‬وتاريــخ‬\n      ‫‪1432/10/19‬ه ـ املتعلقــة بدعــوى (‪ )........‬ضــد (‪ )........‬ففــي هــذا اليــوم‬\n      ‫األحــد املوافــق ‪1432/11/04‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 15‬‬\n      ‫وفيهــا حضــرت (‪ )........‬بالســجل املدنــي رقــم (‪ )........‬حــال حضــور‬\n      ‫والدهــا املعــرف بهــا (‪ )........‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه ثــم‬\n      ‫أذنــت للمدعيــة يف حتريــر دعواهــا فادعــت قائلــة إن املدعى عليــه (‪)........‬‬\n      ‫زوجــي عقــد علــي بواليــة والــدي بتاريخ ‪1430/8/6‬هـ ودخــل بي الدخول‬\n      ‫الشــرعي ولــم أجنــب أوالدا ونظــرا ألنــه لــم يقــم بتأمــن بيــت الزوجيــة وال‬\n      ‫ينفــق علــي النفقــة الواجبــة عليــه باإلضافــة إلــى أنــه يشــتمني ويضربنــي‬\n      ‫ممــا جعــل احليــاة معــه ال حتتمــل وال تطــاق لــذا فإنــي أطلــب احلكــم عليــه‬\n      ‫بفســخ عقــد نكاحــي منــه هــذه دعــواي وأســأله اجلــواب علمــا بأنــه يقيــم‬\n      ‫يف مدينــة جنــران ويعمــل عســكري يف قــوة الطــوارئ اخلاصــة ورقــم‬\n‫‪285‬‬\n\f‫جوالــه ‪ .........‬هكــذا قالــت لــذا وبنــاء علــى املــادة ‪/10/34‬ه ـ مــن نظــام‬\n‫املرافعــات الشــرعية فقــد قــررت اســتخالف رئيــس احملكمــة العامــة‬\n‫بنجــران أو مــن ينيبــه مــن أصحــاب الفضيلــة قضــاة احملكمــة لســماع‬\n‫جــواب املدعــى عليــه وإبالغــه باحلضــور ثــم وردتنــا أوراق املعاملــة مــن‬\n‫احملكمــة العامــة بنجــران برقــم ‪ 321440285‬يف ‪1432/12/16‬ه ـ‬\n‫املرفــق بهــا صــورة مصدقــة مــن الضبــط اآلتــي نصــه (احلمــد هلل وبعــد‬\n‫فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة بنجــران وبنــاء علــى األوراق‬\n‫الــواردة مــن رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‬\n‫‪ 321385710‬وتاريــخ ‪1432/11/05‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بنجــران املســاعد برقــم ‪ 32524119‬وتاريــخ‬\n‫‪1432/11/13‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321440285‬وتاريــخ‬\n‫‪1432/11/13‬ه ـ واملتضمنــة طلــب اســتخالف فضيلــة رئيــس احملكمــة‬\n‫العامــة بنجــران أو مــن ينيبــه يف ســماع جــواب املدعــى عليــه ‪ ............‬يف‬\n‫الدعــوى املقامــة ضــده مــن املدعيــة ‪ .............‬ونصهــا كمــا وردت إلينــا‬\n‫إن املدعــى عليــه ‪ ...............‬زوجــي عقــد علــي بواليــة والــدي بتاريــخ‬\n‫‪1430/08/06‬ه ـ ودخــل بــي الدخــول الشــرعي ولــم أجنــب أوالدا ونظــرا‬\n‫ألنــه لــم يقــم بتأمــن بيــت الزوجيــة وال ينفــق علــي النفقــة الواجبــة عليــه‬\n‫باإلضافــة إلــى أنــه يشــتمني ويضربنــي ممــا جعــل احليــاة معــه ال حتتمــل‬\n‫وال تطــاق لــذا فإننــي أطلــب احلكــم عليــه بفســخ عقــد نكاحــي منــه‬\n‫هــذه دعــواي‪ ،‬وعليــه ففــي يــوم األربعــاء ‪1432/11/28‬ه ـ فتحت اجللســة‬\n‫الســاعة ‪ 10 : 00‬وفيهــا حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ...........‬الوكيــل الشــرعي عــن ‪ .........‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل جنــران برقــم ‪ 32337432‬وتاريــخ‬\n\n\n                                                                                       ‫‪286‬‬\n\f      ‫‪1432/11/26‬ه ـ واملخــول لــه فيهــا حــق املطالبــة واملداعــاة واملخاصمــة‬\n      ‫وســماع الدعــاوى والــرد عليهــا وإقامــة البينــة والدفــع وقبــول احلكــم‬\n      ‫واالعتــراض عليــه وذلــك يف أي قضيــة تقــام منــه أو ضــده وبعــرض دعــوى‬\n      ‫املدعيــة علــى املدعــى عليــه وكالــة أجــاب قائــا مــا ذكرتــه املدعيــة يف‬\n      ‫دعواهــا مــن أنهــا زوجــة ملوكلــي وأنــه دخــل بهــا الدخــول الشــرعي وأنــه‬\n      ‫ال يوجــد منهــا أوالد فذلــك كلــه صحيــح ومــا ذكرتــه املدعيــة مــن أن‬\n      ‫موكلــي لــم يقــم بتأمــن ســكن لهــا وأنــه ال ينفــق عليهــا ويشــتمها‬\n      ‫ويضربهــا فذلــك كلــه غيــر صحيــح فاملدعــى عليــه هــو ابنــي واملدعيــة‬\n      ‫لــم تبقــى يف بيتــه إال أربعــة أشــهر تقريبــا ثــم ذهبــت لبيــت أهلهــا ورفضــت‬\n      ‫العــودة مــرة أخــرى مــع العلــم أنــه مت تأمــن ســكن لهــا خــاص يف‬\n      ‫احملافظــة التــي نســكنها وكذلــك يف جنــران إال أنهــا رفضــت الرجــوع‬\n      ‫لذلــك فــإن موكلــي يريــد مــن زوجتــه الرجــوع لبيتهــا أو إعــادة مــا مت‬\n      ‫دفعــه لهــا إذا كانــت ال تريــد الرجــوع هكــذا أجــاب وأمــرت بإعــادة‬\n      ‫األوراق لفضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة مشــتملة‬\n      ‫علــى صــورة مصدقــة ملــا مت ضبطــه إ‪.‬هــ‪ .‬ويف يــوم الســبت ‪1433/05/08‬‬\n      ‫ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعيــة املعــرف بهــا مــن قبــل املدعــى‬\n      ‫عليــه ‪ ........... /‬ســجل مدنــي رقــم ……… احلاضــر معهــا ثــم جــرى تــاوة‬\n      ‫مــا ســبق رصــده علــى املدعــى عليــه فصادق على جواب وكيله الشــرعي‬\n      ‫املرصــود ســلف ًا ثــم عرضــت ذلــك علــى املدعيــة فأجابــت قائلــة إنــي لســت‬\n      ‫ا فعيشــي معــه أصبــح‬        ‫موافقــة علــى مــا جــاء يف جوابــه جملــة وتفصي ـ ً‬\n      ‫ال فــا هــو ينفــق علــي وال هــو يعاملنــي املعاملــة احلســنة الواجبــة‬‫مســتحي ً‬\n      ‫لــي كزوجــة حفــظ لهــا عقــد الزوجيــة الغليــظ حقهــا لــذا فلــن أعــود إليــه‬\n      ‫مهمــا كلفنــي األمــر هكــذا قالــت ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n\n\n‫‪287‬‬\n\f‫ا إن الصحيــح هــو مــا جــاء يف جــواب موكلــي ســابق ًا فأنــا‬     ‫أجــاب قائ ـ ً‬\n‫ال يف ديرتنــا قريــة جنــاب‬‫أنفــق عليهــا وقــد ســبق وأن أمنــت منــز ًال مســتق ً‬\n‫التابعــة ملركــز الفيــض التابــع لظهــران اجلنــوب هكــذا قــال ثــم ســألت‬\n‫املدعيــة هــل لديهــا البينــة علــى دعواهــا فأجابــت بالنفــي ثــم جــرى وعــظ‬\n‫الزوجــة بالتحلــي بالصبــر والســمع والطاعــة لزوجهــا فأصــرت علــى‬\n‫موقفهــا ثــم جــرى وعــظ الــزوج املدعــى عليــه بأنــه ليــس مــن الشــهامة وال‬\n‫املــروءة ظلــم املــرأة وهضمهــا حقهــا فإمــا إمســاك مبعــروف أو تســريح‬\n‫بإحســان فأصــر علــى موقفــه ثــم ســألتهما اختيــار حكمــن مــن أهلهمــا‬\n‫فأجابــا بأنــه ليــس هنــاك مــن أهلهمــا مــن هو أهل لتولي مهمــة التحكيم‬\n‫عليــه واألمــر مــا ذكــر قــررت إحالــة أوراق املعاملــة لهيئــة النظــر للوقــوف‬\n‫علــى حــال املتداعيــن واإلفــادة علــى مرئياتهــا حيالهمــا مــن جمــع أو‬\n‫فرقه بعوض أو دونه ويف يوم الســبت ‪ 1433/10/21‬هـ افتتحت اجللســة‬\n‫وفيهــا حضــرت املدعيــة حــال حضــور والدها املعــرف بهــا ‪ ...........‬وحضر‬\n‫حلضورهمــا املدعــى عليــه وكالــة ‪ ...........‬بالوكالــة عــن ‪............‬‬\n‫بالســجل املدنــي رقــم ‪ ...........‬الصــادرة مــن كتابــة جنــران عــدل برقــم‬\n‫‪ 32337432‬يف ‪1432/11/26‬ه ـ املخــول لــه فيهــا املداعــاة واملخاصمــة‬\n‫وســماع الدعــاوي والــرد عليهــا وإقامــة البينــة والدفــع وقبــول احلكــم‬\n‫واالعتــراض عليــه وكانــت أوراق املعاملــة قــد عــادت مــن هيئــة النظــر‬\n‫بالقــرار رقــم ‪ 321615377‬يف ‪1433/6/3‬ه ـ املتضمــن الــذي نــراه‬\n‫التفريــق بينهمــا بعــوض يعــاد لــه نصــف املهــر كــون املذكــور تــرك‬\n‫زوجتــه عنــد أهلهــا ملــدة ثــاث ســنوات دون معاجلــة أ‪.‬هــ‪ .‬وبعرضــه مــع‬\n‫املتداعيــن احلاضريــن قــررت املدعيــة موافقتهــا عليــه بينمــا رفضــه‬\n‫املدعــي عليــه وكالــه ثــم ســألتهما عــن مقــدار املهــر فأجابــا بــأن عقــد‬\n\n\n                                                                                       ‫‪288‬‬\n\f      ‫النــكاح تضمــن أن املهــر خمســن ألــف ريــال هكــذا قــال ثــم طلبــت مــن‬\n      ‫املدعيــة إحضــار عــوض اخللــع فطلبــت مهلــة إلحضــاره ويف يــوم األربعــاء‬\n      ‫‪1433/12/22‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعيــة حــال حضــور‬\n      ‫والدهــا املعــرف بهــا وحضــر حلضورهمــا املدعــى عليــه ‪ ..........‬بالســجل‬\n      ‫املدنــي رقــم ……… ثــم ســألت املدعيــة عــن عــوض اخللــع فقالــت قــد‬\n      ‫أحضرتــه وهــو العــوض البالــغ خمســة وعشــرين ألــف ريــال مبوجــب‬\n      ‫شــيك مصــريف مســحوب علــى مصــرف الراجحــي برقــم ‪ 915283‬يف‬\n      ‫‪2012/11/5‬م ممثــل ملبلــغ العــوض وباالطــاع وجدتــه كمــا ذكــرت‬\n      ‫املدعيــة وبعرضــه علــى املدعــى عليــه رفضــه فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة ومــا قررتــه هيئــة النظــر مــن التفريــق بــن املتداعيــن‬\n      ‫علــى نصــف املهــر وإلقرارهمــا بــأن مقــدار املهــر خمســون ألــف ريــال وملــا‬\n      ‫مت مــن وعظهمــا وتوجيههمــا وإلصــرار كل منهمــا علــى رأيــه ولعمــوم‬\n      ‫قولــه تعالــى (وإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n      ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا إن اهلل كان‬\n      ‫عليمــا خبيــرا) وملــا رواه البخــاري عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‬\n      ‫جــاءت امــرأة ثابــت بــن قيــس إلــى النبــي صلــى اهلل عليــه وســلم فقالــت يــا‬\n      ‫رســول اهلل مــا أنقــم علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف الكفــر‬\n      ‫يف اإلســام فقــال رســول اهلل صلــى اهلل عليــه وســلم أترديــن عليــه‬\n      ‫حديقتــه قالــت نعــم فــردت عليــه فأمــره ففارقهــا) ولقولــه عليــه الســام‬\n      ‫(ال ضــرر وال ضــرار) وملــا رواه النســائي وعبدالــرزاق عــن ابــن عبــاس‬\n      ‫رضــي اهلل عنهمــا قــال (بعثــت أنــا ومعاويــة حكمــن قــال معمــر بلغنــي‬\n      ‫أن عثمــان بعثهمــا وقــال إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن‬\n      ‫تفرقــا ففرقــا) وملــا رواه الــدار قطنــي والنســائي والشــافعي والبيهقــي‬\n\n\n‫‪289‬‬\n\f‫عــن محمــد بــن ســيرين عــن عبيــدة قــال جــاء رجــل وامــرأة إلــى علــي مــع‬\n‫كل واحــد منهمــا فئــام مــن النــاس فأمرهــم فبعثــوا حكمــا مــن أهلــه‬\n‫وحكمــا مــن أهلهــا وقــال للحكمــن هــل تدريــا مــا عليكمــا إن رأيتمــا‬\n‫أن جتمعــا فاجمعــا وإن رأيتمــا أن تفرقــا فرقتمــا فقالــت املــرأة رضيــت‬\n‫بكتــاب اهلل مبــا علــي فيــه ولــي وقــال الــزوج أمــا الفرقــة فــا فقــال علــي‬\n‫كذبــت واهلل ال تبــرح حتــى تقــر مثــل الــذي أقــرت بــه) قــال ابــن حجــر‬\n‫إســناده صحيــح وملــا أخرجــه الطبــري يف تفســيره عــن ابــن عبــاس رضــي‬\n‫اهلل عنهمــا يف احلكمــن أنــه قــال فــإن اجتمــع أمرهمــا علــى أن يفرقــا أو‬\n‫يجمعــا فأمرهمــا جائــز ونظــرا إلــى أن اســتمرار احليــاة الزوجيــة علــى‬\n‫هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح يف الشــريعة مــن املــودة‬\n‫والرحمــة والســكن والعفــة مــع مــا يف ذلــك مــن املضــار النفســية‬\n‫واالجتماعيــة علــى الزوجــن مــع مــا ينشــأ عــن ذلــك مــن الظلــم واإلثــم‬\n‫والقطيعــة بــن األســر وتوليــد العــداوة والبغضــاء بنــاء علــى ذلــك فقــد‬\n‫فســخت نــكاح املدعيــة ‪ .........‬مــن زوجهــا املدعــى عليــه ‪ ..............‬علــى‬\n‫عــوض قــدره خمســة وعشــرين ألــف ريــال وبذلــك حكمــت وأفهمــت‬\n‫املدعيــة بــأن عليهــا العــدة الشــرعية وهــي ثــاث حيــض اعتبــارا مــن اليــوم‬\n‫‪1433/12/22‬ه ـ وأفهمــت املدعــى عليــه بــأن زوجتــه املدعيــة قــد بانــت‬\n‫مــن بينونــة صغــرى ال حتــل لــه إال بعقــد جديــد وبعــرض ذلــك علــى‬\n‫الطرفــن قــررت املدعيــة القناعــة وقــرر املدعــى عليــه عدمهــا وطلــب‬\n‫اســتئناف احلكــم فأجيــب لطلبــه وأفهمتــه مبراجعــة احملكمــة خــال‬\n‫عشــرة أيــام مــن تاريخــه الســتالم نســخة مــن احلكــم وتقــدمي الالئحــة‬\n‫االعتراضيــة خــال مــدة االعتــراض وهــي ثالثــون يومــا فــإن لــم يفعــل‬\n‫خاللهــا فــإن حقــه يف االســتئناف يســقط ويكتســب احلكــم القطعيــة‬\n\n\n                                                                                       ‫‪290‬‬\n\f      ‫وأفهمــت املدعيــة بــأال تتــزوج حتــى يكتســب احلكــم القطعيــة وقــررت‬\n      ‫حفــظ العــوض يف بيــت املــال لصالــح املدعــى عليــه وبــاهلل التوفيــق ‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n      ‫‪1433/12/22‬ه ـ احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .............‬خلــف فضيلــة‬\n      ‫الشــيخ ‪ ..........‬القاضــي األســبق بهــذه احملكمــة حيــث عــادت أوراق‬\n      ‫املعاملــة مــن محكمــة االســتئناف باخلطــاب رقــم ‪ 34512580‬يف‬\n      ‫‪1434/4/14‬ه ـ رفقهــا الصــك الشــرعي رقــم ‪ 33483169‬يف‬\n      ‫‪1433/12/29‬ه ـ مظهــر ًا عليــه بقــرار الدائــرة األولــى لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n      ‫االســتئناف مبكة املكرمة رقم ‪ 3457239‬يف ‪1434/3/8‬هـ املتضمن‬\n      ‫أنــه بدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم قاضــي اســتئناف ختــم وتوقيــع ‪ ........... /‬لــي وجهة نظر ‪ /‬قاضي‬\n      ‫اســتئناف ختــم وتوقيــع ‪ / ........... /‬رئيــس الدائــرة ختــم وتوقيــع ‪.......... /‬‬\n      ‫وبذلــك يكــون احلكــم املكتســب القطعيــة وصلــى اهلل علــى نبينــا‬\n                            ‫محمد وعلى آله وصحبه وسلم حرر يف ‪1434/5/6‬هـ‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n      ‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع‬\n      ‫علــى الصــك رقــم ‪ 33483169‬وتاريــخ ‪1433/12/29‬ه ـ الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ...........‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n      ‫املتضمــن فســخ نــكاح املدعيــة ‪ ............‬مــن زوجهــا املدعــى عليــه ‪.........‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه تقــرر باألكثريــة املوافقة على احلكم‬\n        ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪291‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":282,"source_page_end":291,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"263322e5da1d65cbc12a6ae2930d01d72b8bdac8ddff26320667003657561be3","normalized_text_hash":"6003c02d7641f17aeb02af740a11dc0f145f3cf76cd1ecb786c292b0c7dbb678","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p282-33483169"},{"id":"f23c2dc9-30ce-5715-a6f1-ac525c810eca","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -مطالبة الزوجة فسخ النكاح بعد الدخول ملرض الزوج النفسي -إيجابية التقرير الطبي -مصادقة الولي على الدعوى - احلكم بالفسخ دون عوض ملرض الزوج النفسي .","document_number":"34168437","case_number":"32471708","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد باملدينة املنورة ب","circuit":"الدائرة الثالثة لألحوال","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"فسخ نكاح -مطالبة الزوجة فسخ النكاح بعد الدخول ملرض الزوج النفسي -إيجابية التقرير الطبي -مصادقة الولي على الدعوى - احلكم بالفسخ دون عوض ملرض الزوج النفسي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/22 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34168437 :‬‬\n                   ‫َر ْق ُم الدعوى‪32471708 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34238088‬تاريخه‪1434/6/12:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬مطالبــة الزوجــة فســخ النــكاح بعــد الدخــول ملــرض الــزوج‬\n‫النفســي ‪ -‬إيجابيــة التقريــر الطبــي ‪ -‬مصادقــة الولــي علــى الدعــوى ‪-‬‬\n                     ‫احلكــم بالفســخ دون عــوض ملــرض الــزوج النفســي ‪.‬‬\n\n\n\n\n                                       ‫وه َّن ِض َر ًارا»‬\n                                                       ‫‪ .1‬قوله تعالى‪« : :‬و ال ُت ِس ُك ُ‬\n‫‪ .2‬قولــه ص َّلــى اهلل عليــه و علــى آلــه و سـ َّلم ‪ -‬يف قصــة ثابــت بــن قيــس‬\n‫بــن شـ َّـماس مــع امرأتــه ‪ -‬رضــي اهلل عنهمــا ‪« :-‬خــذ احلديقــة ‪ ،‬و ط ِّلقهــا‬\n‫ـاري‪ ،‬و األصــل يف األمــر الوجــوب‪ُ ( ،‬ينظــر‬     ‫تطليقـ ًة» أخرجــه اإلمــام البخـ ُّ‬\n‫محمــد بــن إبراهيــم‬  ‫َّ‬     ‫الشــيخ‬\n                                    ‫الســام ‪ ،299/3‬فتــاوى و رســائل َّ‬              ‫ُسـ ُـبل َّ‬\n                                                                                    ‫‪.)288/10‬‬\n‫«فأمــا‬\n    ‫‪ .3‬مــا قـ َّـرره اإلمــام ابــن العربـ ِّـي املالكـ ِّـي ‪ -‬رحمــه اهلل ‪ -‬بقولــه‪َّ :‬‬\n‫عقــود األبــدان‪ ،‬فــا تتـ ُّـم َّإل باال ِّتفــاق‪ ،‬و ال َّتآلــف‪ ،‬و حســن ال َّتعاشــر‪ ،‬فــإذا‬\n‫الفرقــة‪،‬‬‫فُ قِ ـ َـد ذلــك لــم يكــن لبقــاء العقــد وجـ ٌه‪ ،‬و كانــت املصلحــة يف ُ‬\n‫ـأي وجـ ٍه رأياهــا مــن املتاركــة ‪ ،‬أو أخــذ شــيءٍ مــن الـ َّزوج أو ال َّزوجــة»‬     ‫و بـ ِّ‬\n                                        ‫ا‪ .‬ه ـ ( ُينظــر أحــكام القــرآن ‪.)425/1‬‬\n      ‫رعية و لوائحه ال َّتنفيذ َّية ‪.‬‬\n                                  ‫الش َّ‬\n                                      ‫‪ .4‬املا َّدة (‪ )179‬من نظام املرافعات َّ‬\n\n\n\n\n                                                                                                   ‫‪292‬‬\n\f      ‫ادعــى املدعــي وكالــة أن املدعــى عليــه تــزوج موكلتــه بواليــة أخيهــا‬\n      ‫مقدمـ ًة‪ ،‬بشــرط إكمــال‬‫علــى مهـ ٍـر قــدره خمسـ ٌة وعشــرون ألــف ريــال َّ‬\n      ‫ـرعي‪ ،‬ومكثــت معــه قرابــة تســع‬      ‫الشـ َّ‬ ‫الدخــول َّ‬   ‫الدراســة‪ ،‬وأنــه دخــل بهــا ُّ‬     ‫ِّ‬\n      ‫وجيــة ثالثــة أوالدٍ‪ ،‬وبعــد زواجــه‬    ‫الز َّ‬\n                                                   ‫ـنوات‪ ،‬وولـ َـدت لــه علــى فــراش َّ‬         ‫سـ ٍ‬\n      ‫ـرض نفسـ ٍّـي‪ ،‬و ال ُيحســن ال َّتصــرف ‪،‬‬         ‫بهــا‪ ،‬ا َّتضــح أ َّنــه يعانــي مــن مـ ٍ‬\n      ‫و يعاملهــا معامل ـ ًة ســيئ ًة‪ ،‬و ال يهتـ ُّـم بهــا و ال بأبنائهــا املذكوريــن‪،‬‬\n      ‫أن يتعالــج و يصلــح حالــه؛ و‬      ‫وأنهــا صبــرت عليــه طيلــة هــذه املـ َّـدة رجــاء َّ‬\n      ‫كذلــك مــن أجــل أبنائهــا املذكوريــن‪ ،‬ولكــن دون جــدوى‪ ،‬و يف عــام‬\n      ‫وموكلتــه‬\n              ‫ِّ‬     ‫تصرفــات شــنيعة ومنـ ُّـذ ذلــك اليــوم‬   ‫ُّ‬      ‫(‪1430‬هــ) حصلــت منــه‬\n      ‫عنــد والدتهــا‪ ،‬وطلــب ا ُحلكــم بفســخ نكاحهــا منــه ‪ -‬ورد ال َّتقريــر‬\n      ‫املتضمــن أن املدعــى عليــه يعانــي مــن ذهــانٍ فصامـ ٍّـي‬       ‫ِّ‬                          ‫ِّ‬\n                                                                                  ‫الطبــي ال َّنفسـ ِّـي‬\n      ‫ـمعيةٍ‪،‬‬\n         ‫إضطهاديـةٍ‪ ،‬و هــاوس سـ َّ‬\n                             ‫َّ‬        ‫ٍ‬\n                                      ‫ـاالت‬ ‫مزمـ ٍـن مــع ضــاالت عظمـ ٍة و ضـ‬\n      ‫مت عرضه‬ ‫ـتبصر بحالتــه‪ ،‬و يرفــض العالج بســبب ذلك‪ ،‬و َّ‬\n                                                         ‫ٍ‬   ‫و هــو غيــر مسـ‬\n      ‫احملليــة ورأت أ َّنــه ال ُيحســن ال َّتصــرف يف نفســه و‬\n                                                             ‫َّ‬      ‫الطبيــة‬\n                                                                        ‫َّ‬     ‫علــى اللجنــة‬\n      ‫شــؤونه‪ ،‬و بحاج ـ ٍة إلــى إقامــة ولـ ٍّـي عليــه ‪ -‬حضــر والــد املدعــى عليــه‪،‬‬\n      ‫وليـ ًا عليــه وبعــرض دعــوى املدعيــة عليــه صــادق عليهــا جملـ ًة و تفصيـ ًـا‪،‬‬\n      ‫املدعــى عليــه‬\n                   ‫وقــرر أنــه ال مانــع لديــه مــن فســخ نــكاح املدعيــة مــن ابنــه َّ‬\n      ‫املدعــى عليــه واليــة قــد صــادق علــى دعــوى املدعــي‬       ‫بــدون مقابـ ٍـل ‪َّ -‬‬\n                  ‫وكالــة ‪ -‬اهلل تبــارك وتعالــى نهــى عــن إمســاك ال ِّنســاء ِضـ ً‬\n      ‫ـرارا‪ ،‬فقــال‬\n      ‫الضــر ‪ -‬مت‬                   ‫وه َّن ِضـ َـر ًارا»؛ و ملشـ َّ‬\n                ‫ـروعية رفــع هــذا ُّ‬                               ‫ســبحانه «و ال تُ ِسـ ُ‬\n                                                                 ‫ـك ُ‬\n      ‫املدعــى عليــه وأفهــم‬\n                           ‫احلكــم بفســخ نــكاح املدعيــة أصالــة مــن زوجهــا َّ‬\n\n‫‪293‬‬\n\f‫املدعــى عليــه بينونـ ًة ُصغــرى ‪،‬‬   ‫موكلتــه بانــت مــن َّ‬ ‫ـأن ِّ‬ ‫املدعــي وكالـ ًة بـ َّ‬\n                                                                                          ‫َّ‬\n‫أن عليهــا ال ِعـ َّـدة‬\n                     ‫ـتوف لشــروطه و أركانــه‪ ،‬و َّ‬       ‫ال حت ُّــل لــه َّإل بعقــدٍ مسـ ٍ‬\n‫ـداء مــن تاريــخ احلكــم ‪ -‬بإعــان ا ُحلكــم علــى‬        ‫ـرعية لهــذا الفســخ ابتـ ً‬\n                                                                                   ‫الشـ َّ‬   ‫َّ‬\n‫ـفوعا بصــورة ضبطــه مــع كامــل‬        ‫املتداعيــن‪ ،‬قنعــا بــه‪ُ -‬رفــع ا ُحلكــم مشـ ً‬\n‫أوراق املعاملــة إلــى محكمــة االســتئناف؛ لتدقيقــه عمـ ًـا باملــا َّدة (‪)179‬‬\n‫نفيذيــة ‪ -‬ورد احلكــم مــن‬ ‫َّ‬    ‫ـرعية و لوائحــه ال َّت‬\n                                                        ‫الشـ َّ‬ ‫مــن نظــام املرافعــات َّ‬\n                                                   ‫محكمــة االســتئناف مصدق ـ ًا ‪.‬‬\n\n\n\n\n‫أمــا بعــد‪:‬‬‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬\n                                                       ‫الصــاة و َّ‬‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫الشــيخ (‪ )........‬القاضــي باحملكمــة‬           ‫ـدي (‪ )........‬القائــم بعمــل فضيلــة َّ‬\n                                                                                       ‫فلـ َّ‬\n‫ـعودي اجلنسـ َّـي ِة‬\n                ‫العامــة يف املدينــة املنـ َّـورة‪ .‬حضــر املواطــن (‪ُ )........‬سـ ُّ‬    ‫َّ‬\n‫ـرعي عن املواطنة‬    ‫الشـ ِّ‬\n                          ‫الســجلِّ املدنـ ِّـي رقــم (‪ )..............‬الوكيــل َّ‬\n                                                                               ‫مبوجــب ِّ‬\n‫الســجلِّ املدنـ ِّـي رقــم (‪ ).............‬و‬  ‫ـعودية اجلنسـ َّـي ِة مبوجــب ِّ‬\n                                                                            ‫(‪ُ )........‬سـ َّ‬\n‫الصــادرة مــن كتابــة العــدل‬         ‫املخولــة َّ‬‫ِّ‬    ‫وكلــه مبوجــب الوكالــة‬ ‫ا َّلــذي َّ‬\n‫الثَّانيــة يف املدينــة املنـ َّـورة برقــم (‪ )33481366‬يف ‪1433/12/26‬هــ‪ ،‬و‬\n‫ـعودي اجلنسـ َّـي ِة‬\n                 ‫ا َّدعــى علــى الغائــب عــن مجلــس القضــاء (‪ُ )........‬سـ ِّ‬\n‫املدعــى‬  ‫إن َّ‬‫الســجلِّ املدنـ ِّـي رقــم (‪ .)............‬قائـ ًـا يف دعــواه‪َّ :‬‬\n                                                                               ‫مبوجــب ِّ‬\n‫الصحيــح‪ ،‬بواليــة أخيهــا‬  ‫تزوجهــا بالعقــد َّ‬    ‫ملوكلتــي‪َّ ،‬‬  ‫زوج ِّ‬‫عليــه (‪ٌ )........‬‬\n‫(‪ )........‬بتاريــخ ‪1422/03/24‬هــ‪ ،‬علــى مهـ ٍـر قــدره خمس ـ ٌة و عشــرون‬\n‫مقدم ـ ًة‪ ،‬اســتلم ُتها كامل ـ ًة ‪ ،‬بشــرط إكمــال‬         ‫ألــف (‪ )25,000‬ريــالٍ َّ‬\n‫ـرعي بتاريــخ ‪1422/03/27‬هــ‪،‬‬         ‫الشـ َّ‬\n                                           ‫الدخــول َّ‬  ‫الدراســة‪ ،‬و قــد دخــل بهــا ُّ‬  ‫ِّ‬\n‫ـنوات‪ ،‬و ولـ َـدت لــه علــى فــراش‬    ‫و مكثــت معــه قرابــة تســع (‪ )9‬سـ ٍ‬\n\n                                                                                                  ‫‪294‬‬\n\f      ‫وجيــة ثالثــة أوال ٍد هــم كلٌّ مــن (‪ ،»......« )1‬و املولــودة يف‬                                  ‫الز َّ‬ ‫َّ‬\n      ‫تقريبــا‪)2( .‬‬\n               ‫ً‬          ‫‪1423/10/10‬هــ‪ ،‬و عمرهــا اآلن عشــر (‪ )10‬سـ ٍ‬\n                          ‫ـنوات‬\n      ‫«‪ ،»........‬و املولــودة يف ‪1426/11/28‬هــ‪ ،‬و عمرهــا اآلن ثمــان (‪)08‬‬\n      ‫تقريبــا‪ ،».........« )3( .‬و املولــود يف ‪1429/04/11‬هــ‪ ،‬و عمــره‬                           ‫ً‬          ‫سـ ٍ‬\n                                                                                                          ‫ـنوات‬\n      ‫تقريبــا‪ .‬و بعــد زواجــه بهــا‪ ،‬ا َّتضــح أ َّنــه يعانــي من‬  ‫ً‬          ‫اآلن خمــس (‪ )5‬سـ ٍ‬\n                                                                               ‫ـنوات‬\n      ‫ـرض نفسـ ٍّـي‪ ،‬و ال ُيحســن ال َّتصــرف‪ ،‬و يعاملهــا معامل ـ ًة ســيئ ًة‪ ،‬و ال‬                          ‫مـ ٍ‬\n      ‫موكلتــي طيلــة‬  ‫يهتـ ُّـم بهــا و ال بأبنائهــا املذكوريــن ‪ ،‬و قــد صبــرت عليــه ِّ‬\n      ‫أن يتعالــج و يصلــح حالــه؛ و كذلــك مــن أجــل أبنائهــا‬                         ‫هــذه املـ َّـدة رجــاء َّ‬\n      ‫الســيئة يف ازديــادٍ‪ ،‬و‬  ‫فتصرفاتــه َّ‬ ‫ُّ‬            ‫املذكوريــن ‪ ،‬و لكــن دون جــدوى‪،‬‬\n      ‫تصرفــات شــنيعة كمحاولتــه اشــعال‬                ‫ُّ‬      ‫يف عــام (‪1430‬هــ) حصلــت منــه‬\n      ‫ملوكلتــي و أوالده‪ ،‬و‬       ‫ِّ‬      ‫النــار يف املنــزل‪ ،‬و ال َّتهديــد املســتمر بالقتــل‬\n      ‫ات‪ ،‬و منـ ُّـذ ذلــك اليــوم و ح َّتــى هــذا اليــوم و‬        ‫محاولتــه االنتحــار عِ ـ َّـدة مـ َّـر ٍ‬\n      ‫املدعــى‬\n            ‫أن َّ‬‫ـا‪ .............‬يف املدينــة املنـ َّـورة‪ ،‬و مبــا َّ‬\n                                                               ‫ُ‬                ‫موكلتــي عنــد والدتهـ‬         ‫ِّ‬\n      ‫موكلتــي و وأوالدهــا‬          ‫ِّ‬   ‫ـض نفسـ ٌّـي و حالتــه خطــر ٌة علــى‬                     ‫عليــه مريـ ٌ‬\n      ‫كـ َـر مســتحيل ٌة‪ ،‬أطلــب ا ُحلكــم‬          ‫املذكوريــن ‪ ،‬و احليــاة معــه حيــال مــا ُذ ِ‬\n      ‫بفســخ نكاحهــا منــه‪ ،‬هــذه دعــواي‪ .‬و كان قــد جــرى م َّنــا الكتابــة‬\n      ‫إلــى ســعادة وكيــل إمــارة منطقــة املدينــة املن