ـ ٍة إلــى إقامــة ولـ ٍّـي عليــه» الطبيــب املعالــج دون‬\n‫توقيــع ‪ ،‬املســاعد للشــؤون الفنيــة‪ ............. /‬دون توقيــع ‪ ،‬مديــر‬\n‫الص َّحــة النفسـ َّـية باملدينــة املنـ َّـورة‪ /‬أ‪ ...........‬دون توقيــع ‪ ،‬و يف‬                ‫مستشــفى ِّ‬\n‫هويتــه و كالتــه‬          ‫ـدون َّ‬   ‫جلس ـ ٍة ُأخــرى حضــر املواطــن‪ ،................ /‬املـ َّ‬\n‫ـعودي اجلنسـ َّـي ِة مبوجــب‬      ‫ـابقا ‪ ،‬و حضــر حلضــوره املواطــن‪ُ ،............ /‬سـ ُّ‬                       ‫سـ ً‬\n‫املدعــى عليــه‪/‬‬     ‫الســجلِّ املدنـ ِّـي رقــم (…………‪).‬؛ الولـ ُّـي علــى ولــده َّ‬                               ‫ِّ‬\n‫عمــا‬  ‫املدعــى عليــه واليـ ًة َّ‬       ‫ـابقا ‪ ،‬فجــرى ســؤال َّ‬        ‫هويتــه سـ ً‬\n                                                                                    ‫ـدون َّ‬   ‫‪ ،............‬املـ َّ‬\n‫املدعــي‬   ‫املدعــي وكال ـ ًة‪ ،‬فأجــاب بقولــه‪ :‬مــا ذكــره َّ‬                        ‫جــاء يف دعــوى َّ‬\n‫املدعــى عليــه‪/‬‬       ‫وكال ـ ًة ك ّلــه صحيـ ٌـح جمل ـ ًة و تفصيـ ًـا‪ ،‬فابنــي َّ‬\n‫الصحيــح‪ ،‬بواليــة‬           ‫تزوجهــا بالعقــد َّ‬       ‫للمدعيــة أصال ـ ًة‪َّ ،‬‬   ‫زوج َّ‬   ‫‪ٌ ،................‬‬\n‫أخيهــا‪ ............‬بال َّتاريــخ املشــار إليــه علــى املهــر املذكــور اســتلمته‬\n‫ـرعي‬\n  ‫الشـ َّ‬      ‫الدخــول َّ‬     ‫الدراســة‪ ،‬و قــد دخــل بهــا ُّ‬     ‫كامـ ًـا ‪ ،‬بشــرط إكمــال ِّ‬\n‫ـنوات‪ ،‬و‬  ‫بتاريــخ ‪1422/03/27‬هــ‪ ،‬و مكثــت معــه قرابــة تســع (‪ )9‬سـ ٍ‬\n\n\n                                                                                                                        ‫‪296‬‬\n\f      ‫وجيــة مــن ذكــرت‪ .‬و بعــد زواجــه بهــا‪ ،‬ا َّتضــح‬            ‫الز َّ‬   ‫ولـ َـدت لــه علــى فــراش َّ‬\n      ‫ـرض نفسـ ٍّـي‪ ،‬و ال ُيحســن ال َّتصــرف‪ ،‬و يعاملهــا معاملـ ًة‬                         ‫أ َّنــه يعانــي مــن مـ ٍ‬\n      ‫ســيئ ًة‪ ،‬و ال يهتـ ُّـم بهــا و ال بأبنائهــا املذكوريــن ‪ ،‬و قــد صبــرت عليــه‬\n      ‫أن يتعالــج و يصلــح حالــه؛ و كذلــك م