كيــل إمــارة منطقــة املدينــة املنـ َّـورة باخلطــاب رقــم‬\n      ‫املدعــى عليــه‪ ،‬و‬   ‫(‪ )33/1073854‬يف ‪1433/06/08‬هــ؛ للبحــث عــن َّ‬\n      ‫الص َّحــة ال َّنفسـ َّـية يف املدينــة املنـ َّـورة‪ ،‬و الكشــف‬        ‫إيداعــه يف مستشــفى ِّ‬\n      ‫العقليــة لــه‪ ،‬هــل‬\n                    ‫َّ‬        ‫ني‪ ،‬و اإلفــادة عــن احلالــة‬       ‫عليــه مــن قبــل طبيبــن مســلم ِ‬\n      ‫ـادر على تصريف شــؤونه‬            ‫للزمــان و املــكان أم ال؟ و هــل هــو قـ ٌ‬             ‫ـدرك َّ‬ ‫هــو مـ ٌّ‬\n      ‫و أمالكــه أم ال؟ و هــل هــو بحاج ـ ٍة إلقامــة ولـ ٍّـي عليــه أم ال؟ فوردنــا‬\n      ‫العزيزيــة رقــم (‪ )2319397/22‬يف‬           ‫َّ‬            ‫خطــاب مديــر مركــز شــرطة‬\n\n\n‫‪295‬‬\n\f‫املقيــد بأســاس هــذه احملكمــة برقــم‬                               ‫َّ‬        ‫‪1433/10/25‬هــ‪ ،‬و‬\n‫(‪ )33/1919210‬يف ‪1433/10/29‬هــ‪ ،‬مرفـ ٌـق بــه خطــاب مديــر‬\n‫الص َّحــة ال َّنفسـ َّـية باملدينــة املنـ َّـورة رقــم (‪ )3/756‬يف‬                         ‫مستشــفى ِّ‬\n‫الطبــي ال َّنفسـ ِّـي رقــم (‪)3/2523‬‬                ‫‪1433/10/16‬هــ‪ ،‬مرفـ ٌـق بــه ال َّتقريــر ِّ‬\n‫ـص احلاجــة منــه‪ « :‬املذكــور‬                    ‫املتضمــن مــا نـ ُّ‬\n                                                                 ‫ِّ‬           ‫يف ‪1433/07/28‬هــ‪ ،‬و‬\n‫أن تنــوم‬    ‫ـف يف املستشــفى مــن تاريــخ ‪1422/08/15‬ه وســبق َّ‬                                  ‫أعــاه لــه ملـ ٌ‬\n‫مزمن مع ضالالت‬           ‫ٍ‬          ‫يف املستشــفى لدينــا‪ ،‬و هــو يعانــي مــن ذهانٍ فصامـ ٍّـي‬\n‫ـتبصر‬\n‫ٍ‬              ‫ـمعيةٍ‪ ،‬و هو غير مسـ‬         ‫إضطهاديةٍ‪ ،‬و هالوس سـ َّ‬      ‫َّ‬             ‫ٍ‬\n                                                                                        ‫ضالالت‬           ‫عظم ٍة و‬\n‫الطبية‬\n    ‫َّ‬           ‫مت عرضــه علــى اللجنة‬         ‫بحالتــه‪ ،‬و يرفــض العــاج بســبب ذلــك‪ ،‬و َّ‬\n‫احملليــة بتاريــخ ‪1433/07/23‬هــ‪ ،‬و رأت أ َّنــه ال ُيحســن ال َّتصــرف يف‬                                    ‫َّ‬\n‫نفســه و شــؤونه‪ ،‬و بحاجـ ٍة إلــى إقامــة ولـ ٍّـي عليــه» الطبيــب املعالــج دون‬\n‫توقيــع ‪ ،‬املســاعد للشــؤون الفنيــة‪ ............. /‬دون توقيــع ‪ ،‬مديــر‬\n‫الص َّحــة النفسـ َّـية باملدينــة املنـ َّـورة‪ /‬أ‪ ...........‬دون توقيــع ‪ ،‬و يف‬                ‫مستشــفى ِّ‬\n‫هويتــه و كالتــه‬          ‫ـدون َّ‬   ‫جلس ـ ٍة ُأخــرى حضــر املواطــن‪ ،................ /‬املـ َّ‬\n‫ـعودي اجلنسـ َّـي ِة مبوجــب‬      ‫ـابقا ‪ ،‬و حضــر حلضــوره املواطــن‪ُ ،............ /‬سـ ُّ‬                       ‫سـ ً‬\n‫املدعــى عليــه‪/‬‬     ‫الســجلِّ املدنـ ِّـي رقــم (…………‪).‬؛ الولـ ُّـي علــى ولــده َّ‬                               ‫ِّ‬\n‫عمــا‬  ‫املدعــى عليــه واليـ ًة َّ‬       ‫ـابقا ‪ ،‬فجــرى ســؤال َّ‬        ‫هويتــه سـ ً‬\n                                                                                    ‫ـدون َّ‬   ‫‪ ،............‬املـ َّ‬\n‫املدعــي‬   ‫املدعــي وكال ـ ًة‪ ،‬فأجــاب بقولــه‪ :‬مــا ذكــره َّ‬                        ‫جــاء يف دعــوى َّ‬\n‫املدعــى عليــه‪/‬‬       ‫وكال ـ ًة ك ّلــه صحيـ ٌـح جمل ـ ًة و تفصيـ ًـا‪ ،‬فابنــي َّ‬\n‫الصحيــح‪ ،‬بواليــة‬           ‫تزوجهــا بالعقــد َّ‬       ‫للمدعيــة أصال ـ ًة‪َّ ،‬‬   ‫زوج َّ‬   ‫‪ٌ ،................‬‬\n‫أخيهــا‪ ............‬بال َّتاريــخ املشــار إليــه علــى املهــر املذكــور اســتلمته‬\n‫ـرعي‬\n  ‫الشـ َّ‬      ‫الدخــول َّ‬     ‫الدراســة‪ ،‬و قــد دخــل بهــا ُّ‬     ‫كامـ ًـا ‪ ،‬بشــرط إكمــال ِّ‬\n‫ـنوات‪ ،‬و‬  ‫بتاريــخ ‪1422/03/27‬هــ‪ ،‬و مكثــت معــه قرابــة تســع (‪ )9‬سـ ٍ‬\n\n\n                                                                                                                        ‫‪296‬‬\n\f      ‫وجيــة مــن ذكــرت‪ .‬و بعــد زواجــه بهــا‪ ،‬ا َّتضــح‬            ‫الز َّ‬   ‫ولـ َـدت لــه علــى فــراش َّ‬\n      ‫ـرض نفسـ ٍّـي‪ ،‬و ال ُيحســن ال َّتصــرف‪ ،‬و يعاملهــا معاملـ ًة‬                         ‫أ َّنــه يعانــي مــن مـ ٍ‬\n      ‫ســيئ ًة‪ ،‬و ال يهتـ ُّـم بهــا و ال بأبنائهــا املذكوريــن ‪ ،‬و قــد صبــرت عليــه‬\n      ‫أن يتعالــج و يصلــح حالــه؛ و كذلــك مــن‬                 ‫املدعيــة طيلــة هــذه املـ َّـدة رجــاء َّ‬           ‫َّ‬\n      ‫الســيئة يف‬\n                ‫فتصرفاتــه َّ‬\n                            ‫ُّ‬           ‫أجــل أبنائهــا املذكوريــن ‪ ،‬و لكــن دون جــدوى‪،‬‬\n      ‫تصرفــات شــنيعة كمحاولته‬             ‫ازديــادٍ‪ ،‬و يف عــام (‪1430‬هــ) حصلــت منــه ُّ‬\n      ‫إشــعال النــار يف املنــزل‪ ،‬و ال َّتهديــد املســتمر بالقتــل للمدعيــة و أوالدهــا‪،‬‬\n      ‫ات‪ ،‬و منـ ُّـذ ذلــك اليــوم و ح َّتــى هــذا اليــوم‬         ‫و محاولتــه االنتحــار عِ ـ َّـدة مـ َّـر ٍ‬\n      ‫ـدي مــن‬\n             ‫و املدعيــة عنــد والدتهــا‪ ............‬يف املدينــة املنـ َّـورة‪ ،‬و ال مانــع لـ َّ‬\n      ‫املدعيــة ‪،................ /‬‬   ‫املدعــى عليــه ‪ ،................ /‬لزوجتــه َّ‬              ‫طــاق ابنــي َّ‬\n      ‫املدعــى عليــه‪ ،‬هــل اســتخرجت‬               ‫هــذا مــا لــدي‪ُ .‬ثـ َّـم جــرى ســؤال والــد َّ‬\n      ‫املدعــى عليــه ؟ فأجــاب بقولــه‪« :‬ال» لــم أســتخرج‬                  ‫صــك واليـ ٍة علــى ابنــك َّ‬\n      ‫صــك والي ـ ٍة علــى ابنــي‪ ،‬هكــذا أجــاب‪ .‬فطلبـ ُـت منــه اســتخراج صــك‬\n      ‫املدعــى عليــه ‪ ،‬و يف جلس ـ ٍة ُأخــرى حضــر املواطــن‪/‬‬                           ‫والي ـ ٍة علــى ابنــه َّ‬\n      ‫ـابقا ‪ ،‬و حضــر حلضــوره املواطن‪/‬‬               ‫هويتــه و وكالتــه سـ ً‬          ‫ـدون َّ‬   ‫‪ ،ِ..............‬املـ َّ‬\n      ‫الســجلِّ املدنـ ِّـي رقــم (‪)................‬؛‬  ‫ـعودي اجلنسـ َّـي ِة مبوجــب ِّ‬         ‫‪ُ ،............‬سـ ُّ‬\n      ‫ـابقا ‪ ،‬فجــرى‬  ‫هويتــه سـ ً‬  ‫ـدون َّ‬   ‫املدعــى عليــه‪ ،........... /‬املـ َّ‬        ‫الولـ ُّـي علــى ولــده َّ‬\n      ‫املدعــى عليــه والي ـ ًة‪ ،‬هــل اســتخرجت صــك والي ـ ٍة علــى ابنــك‬                              ‫ســؤال َّ‬\n      ‫املدعــى عليــه؟ فأجــاب بقولــه‪« :‬نعــم»‪ ،‬فجــرى االطِّ ــاع عليــه فــإذا هــو‬                              ‫َّ‬\n      ‫الرقــم (‪ )33459455‬يف ‪1434/03/10‬هــ‪ ،‬و مــن إجــراء فضيلــة‬                                          ‫يحمــل َّ‬\n      ‫ـدي اســتمرار واليــة‬    ‫ـص احلاجــة منــه‪« :‬فقــد ثبــت لـ َّ‬             ‫الشــيخ‪ ،............. /‬و نـ ُّ‬          ‫َّ‬\n      ‫املنهــي علــى ابنــه‪ »...........« /‬يرعــى شــؤونه و يحافــظ علــى مصاحلــه‪ ،‬و‬\n      ‫الدعــوى و الـ َّـر ِّد عليهــا و إقامــة‬  ‫لــه احلــق يف املداعــاة و املخاصمــة و ســماع َّ‬\n\n‫‪297‬‬\n\f‫كافــة‬‫َّ‬    ‫الرفــع‪ ،‬يف ّأيــش قضيــة تقــام منــه أو ضــده‪ ،‬و إنهــاء‬                         ‫البينــة‪ ،‬و َّ‬   ‫ِّ‬\n‫املدعــى عليــه‬    ‫الدعــوى علــى َّ‬ ‫اإلجــراءات املتعلقــة بذلــك» فجــرى عــرض َّ‬\n‫املدعــي وكال ـ ًة ك ّلــه‬     ‫والي ـ ًة مـ َّـر ًة ُأخــرى‪ ،‬فأجــاب بقولــه‪ :‬مــا ذكــره َّ‬\n‫زوج‬\n  ‫املدعــى عليــه‪ٌ ،................... /‬‬       ‫صحيـ ٌـح جمل ـ ًة و تفصيـ ًـا‪ ،‬فابنــي َّ‬\n‫الصحيــح‪ ،‬بواليــة أخيهــا‪...............‬‬         ‫تزوجهــا بالعقــد َّ‬    ‫للمدعيــة أصال ـ ًة‪َّ ،‬‬            ‫َّ‬\n‫بال َّتاريــخ املشــار إليــه علــى املهــر املذكــور اســتلمته كامـ ًـا ‪ ،‬بشــرط‬\n‫ـرعي بتاريــخ‬  ‫الشـ َّ‬   ‫الدخــول َّ‬   ‫الدراســة‪ ،‬و قــد دخــل بهــا ُّ‬                      ‫إكمــال ِّ‬\n‫ـنوات‪ ،‬و ولـ َـدت لــه‬  ‫‪1422/03/27‬هــ‪ ،‬و مكثــت معــه قرابــة تســع (‪ )9‬سـ ٍ‬\n‫وجيــة مــن ذكــرت‪ .‬و بعــد زواجــه بهــا‪ ،‬ا َّتضــح أ َّنــه يعانــي‬              ‫الز َّ‬ ‫علــى فــراش َّ‬\n‫ـرض نفسـ ٍّـي‪ ،‬و ال ُيحســن ال َّتصــرف‪ ،‬و يعاملهــا معامل ـ ًة ســيئ ًة‪ ،‬و‬                       ‫مــن مـ ٍ‬\n‫املدعيــة طيلــة‬ ‫صبـ َـرت عليــه َّ‬ ‫ال يهتـ ُّـم بهــا و ال بأبنائهــا املذكوريــن ‪ ،‬و قــد َ‬\n‫أن يتعالــج و يصلــح حالــه؛ و كذلــك مــن أجــل أبنائهــا‬                           ‫هــذه املـ َّـدة رجــاء َّ‬\n‫الســيئة يف ازديــادٍ‪ ،‬و‬     ‫فتصرفاتــه َّ‬ ‫ُّ‬       ‫املذكوريــن ‪ ،‬و لكــن دون جــدوى‪،‬‬\n‫تصرفــات شــنيعة؛ كمحاولتــه إشــعال‬                 ‫ُّ‬    ‫يف عــام (‪1430‬هــ) حصلــت منــه‬\n‫للمدعيــة و أوالدهــا‪ ،‬و‬         ‫النــار يف املنــزل‪ ،‬و ال َّتهديــد املســتمر بالقتــل َّ‬\n‫ات‪ ،‬و منـ ُّـذ ذلــك اليــوم و ح َّتــى هــذا اليــوم و‬        ‫محاولتــه االنتحــار عِ ـ َّـدة مـ َّـر ٍ‬\n‫ـدي مــن‬ ‫املدعيــة عنــد والدتهــا‪ .................‬يف املدينــة املنـ َّـورة‪ ،‬و ال مانــع لـ َّ‬\n‫املدعــى عليــه ‪ ،......... /‬بدون‬        ‫املدعيــة ‪ ،............ /‬مــن ابنــي َّ‬       ‫فســخ نــكاح َّ‬\n‫املدعــي وكال ـ ًة‬    ‫أن َّ‬‫ـاء علــى مــا تقـ َّـدم؛ و مبــا َّ‬ ‫مقابـ ٍـل‪ ،‬هــذا مــا لــدي‪ .‬فبنـ ً‬\n‫املدعــى عليــه واليــة قــد صــادق علــى‬               ‫أن َّ‬\n                                                           ‫ا َّدعــى مبــا ا َّدعــى بــه؛ و مبــا َّ‬\n‫دعــواه؛ و ل ــما قـ َّـرره اإلمــام ابــن العربـ ِّـي املالكـ ِّـي ‪ -‬رحمــه اهلل ‪ -‬بقولــه‪:‬‬\n‫«فأمــا عقــود األبــدان‪ ،‬فــا تتـ ُّـم َّإل باال ِّتفــاق‪ ،‬و ال َّتآلــف‪ ،‬و حســن‬                        ‫َّ‬\n‫ال َّتعاشــر‪ ،‬فــإذا ُفقِ ـ َـد ذلــك لــم يكــن لبقــاء العقــد وج ـ ٌه‪ ،‬و كانــت‬\n\n\n                                                                                                                     ‫‪298‬‬\n\f      ‫ـأي وجـ ٍه رأياهــا مــن املتاركــة‪ ،‬أو أخــذ شــي ٍء‬                          ‫الفرقــة‪ ،‬و بـ ِّ‬      ‫املصلحــة يف ُ‬\n      ‫أن‬‫(ينظــر أحــكام القــرآن ‪ ،)425/1‬و مبــا َّ‬                            ‫الزوجــة» ا‪ .‬ه ـ ُ‬         ‫مــن الـ َّـزوج أو َّ‬\n      ‫ـرارا‪ ،‬فقــال ســبحانه يف‬             ‫اهلل تبــارك و تعالــى نهــى عــن إمســاك ال ِّنســاء ِضـ ً‬\n      ‫ـروعية رفــع هــذا‬     ‫َّ‬          ‫وه َّن ِضـ َـر ًارا»؛ و ملشـ‬   ‫ـك ُ‬‫كتابــه الكــرمي‪« :‬و ال تُ ِسـ ُ‬\n      ‫بالفرقَ ــة؛ لقولــه ص َّلــى اهلل عليــه و علــى آلــه و سـلَّم يف قصــة ثابــت‬                              ‫الضــر ُ‬  ‫ُّ‬\n      ‫بــن قيــس بــن شـ َّـماس مــع امرأتــه رضــي اهلل عنهما‪»:‬خــذ احلديقــة‪ ،‬و‬\n      ‫ـاري‪ ،‬و األصــل يف األمــر الوجــوب‪،‬‬                    ‫طلِّقهــا تطليقـ ًة» أخرجــه اإلمــام البخـ ُّ‬\n      ‫محمــد بــن‬   ‫َّ‬          ‫الشــيخ‬\n                                      ‫الســام ‪ ،299/3‬فتــاوى و رســائل َّ‬                               ‫(ينظــر ُسـ ُـبل َّ‬            ‫ُ‬\n      ‫املدعــى عليــه يو َّلــى عليــه مــن قبــل والــده‬                ‫أن َّ‬  ‫إبراهيــم ‪)288/10‬؛ و مبــا َّ‬\n      ‫ـض نفسـ ٌّـي‪ ،‬و ال يهتــم بزوجتــه‬               ‫ـأن االبــن مريـ ٌ‬    ‫احلاضــر ؛ و إلقــرار املولــي بـ َّ‬\n      ‫وجيــة و الـ َّـزوج بهــذه احلالــة؛‬      ‫الز َّ‬  ‫و ال بأبنائهــا؛ و أل َّنــه يتعـ َّـذر قيــام عقــد َّ‬\n      ‫املدعيــة أصال ـ ًة‪ ، .............. /‬مــن‬            ‫ـخت نــكاح َّ‬              ‫لذلــك ك ِّلــه فقــد فسـ ُ‬\n      ‫فهمت‬‫ُ‬       ‫ـوض‪ ،‬و بذلــك قضيـ ُـت‪ ،‬و ُأ‬             ‫املدعــى عليــه‪ ، .......... /‬دون عـ ٍ‬                 ‫زوجهــا َّ‬\n      ‫املدعــى عليــه بينون ًة‬      ‫املدعيــة ‪ -‬بانــت مــن َّ‬        ‫موكلتــه ‪َّ -‬‬      ‫ـأن ِّ‬      ‫املدعــي وكالـ ًة بـ َّ‬     ‫َّ‬\n      ‫أن عليهــا‬       ‫ـتوف لشــروطه و أركانــه‪ ،‬و َّ‬              ‫ُصغــرى‪ ،‬ال حتــلُّ لــه َّإل بعقــدٍ مسـ ٍ‬\n      ‫ـض ابتــد ًأ مــن هــذا‬           ‫ـاث (‪ )3‬حيـ ٍ‬     ‫ـرعية لهــذا الفســخ و هــي ثـ ُ‬                   ‫الشـ َّ‬ ‫ال ِعـ َّـدة َّ‬\n      ‫اليــوم‪ ،‬و بإعــان ا ُحلكــم علــى املتداعيــن‪ ،‬قنعــا بــه‪ ،‬و أمــرت برفــع‬\n      ‫ـفوعا بصــورة ضبطــه مــع كامــل أوراق املعاملــة ‪ -‬إلــى‬                                        ‫ا ُحلكــم ‪ -‬مشـ ً‬\n      ‫محكمــة االســتئناف؛ لتدقيقــه عمـ ًـا باملــا َّدة (‪ )179‬من نظــام املرافعات‬\n      ‫نفيذيــة‪ ،‬و ُحـ ِّـر َر يف ‪1434/03/21‬هــ‪ ،‬و بــاهلل‬                         ‫َّ‬         ‫ـرعية و لوائحــه ال َّت‬   ‫الشـ َّ‬      ‫َّ‬\n      ‫محمــدٍ ‪ ،‬و علــى آلــه وصحبــه‬             ‫نبينــا َّ‬     ‫ال َّتوفيــق‪ ،‬وص َّلــى اهلل وس ـلَّم علــى ِّ‬\n                                                                                                                       ‫أجمعني‪.‬‬\n      ‫أمــا‬ ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬            ‫الصــاة و َّ‬           ‫احلمــد هلل وحــده‪ ،‬و َّ‬\n\n‫‪299‬‬\n\f‫ُكرمــة‬\n     ‫مبكــة امل َّ‬ ‫بعــد‪ :‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف َّ‬\n‫باخلطــاب رقــم (‪ )33263879‬يف ‪1434/6/17‬هــ‪ ،‬و قُ ِّيــدت بأســاس‬\n‫مرفقــا بهــا‬\n           ‫ً‬       ‫احملكمــة برقــم (‪ )33/263879‬يف ‪1434/06/25‬هــ‪،‬‬\n‫الصــادر م ِّنــي برقــم (‪ )34168437‬يف ‪1434/03/22‬هــ‪،‬‬                           ‫اإلعــام َّ‬\n‫ـخصية‪ ،‬و‬\n       ‫َّ‬      ‫الشـ‬\n                 ‫الدائــرة الثَّالثــة لألحــوال َّ‬‫الصــادر مــن َّ‬  ‫ُمظ َّهـ ًـرا بالقــرار َّ‬\n‫القصــار‪ ،‬و بيــوت املــال‪ ،‬برقــم (‪)34238088‬‬            ‫َّ‬    ‫األوقــاف‪ ،‬و الوصايــا‪ ،‬و‬\n‫ـص احلاجــة منــه مــا يلــي‪« :‬بدراســة‬ ‫املتضمــن مــا نـ ُّ‬\n                                                      ‫ِّ‬        ‫يف ‪1434/06/12‬هــ‪ ،‬و‬\n‫الصــك‪ ،‬و صــورة ضبطــه‪ ،‬تقـ َّـررت املوافقــة علــى ا ُحلكــم بفســخ‬\n‫ال ِّنــكاح» ا‪.‬هــ‪ .‬و للبيــان ُحـ ِّـر َر يف ‪1434/06/26‬هــ‪ ،‬وبــاهلل ال َّتوفيــق‪،‬‬\n‫محمــدٍ ‪ ،‬و علــى آلــه و صحبــه أجمعــن‪.‬‬      ‫نبينــا َّ‬   ‫و ص َّلــى اهلل و س ـلَّم علــى ِّ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة املســاعد باملدينــة املنــورة برقــم ‪ 33/263879‬وتاريــخ‬\n‫‪1434/5/27‬ه ـ املرفــق بهــا الصــك ال ــصادر مــن فضيلــة الشــيخ ‪............‬‬\n‫الـق ــاضي باحملكمــة العام ــة باملدينــة املنــورة برقــم ‪ 34168437‬وتاري ــخ‬\n‫‪1434/3/22‬ه ـ ‪ ،‬املتضمــن طلــب املــرأة ‪ ...............‬فســخ نكاحهــا مــن‬\n‫زوجهــا الغائــب عــن مجلــس القضــاء ‪ ، .............‬وبدراســة الصــك وصــورة‬\n‫ضبطــه تقــررت املوافقــة علــى احلكــم بفســخ النــكاح مــع مالحظــة‬\n‫التنبيــه املرفــق‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                                           ‫وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                                  ‫‪300‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":292,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"501a4d40d680922172c37b808ede0c492e52e2658de36c6fe636cf99b46f2f26","normalized_text_hash":"fa715ec7204cfa603bfcb00686f299649679fa0c340e1e681b71f09eb8f27781","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p292-34168437"},{"id":"fc7235c7-28c7-5c44-a14a-9bcf575cd7ca","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -املطالبة بفسخ النكاح للغيبة وعدم النفقة -تبليغ املدعى عليه الغائب عن طريق األمارة واإلعان يف إحدى الصحف -قيام البينة بالشهود املعدلن -احلكم بفسخ النكاح -اإلفهام بالعدة وعدم الزواج إال بعد اخلروج من العدة واكتساب احلكم","document_number":"344668","case_number":"33136760","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/6","year":"1434","subject":"فسخ نكاح -املطالبة بفسخ النكاح للغيبة وعدم النفقة -تبليغ املدعى عليه الغائب عن طريق األمارة واإلعان يف إحدى الصحف -قيام البينة بالشهود املعدلن -احلكم بفسخ النكاح -اإلفهام بالعدة وعدم الزواج إال بعد اخلروج من العدة واكتساب احلكم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/1/6 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪344668 :‬‬\n                         ‫َر ْق ُم الدعوى‪33136760 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3463023‬تاريخه‪1434/3/16:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬املطالبــة بفســخ النــكاح للغيبــة وعــدم النفقــة ‪ -‬تبليــغ‬\n      ‫املدعــى عليــه الغائــب عــن طريــق األمــارة واإلعــان يف إحــدى الصحــف‬\n      ‫‪ -‬قيــام البينــة بالشــهود املعدلــن ‪ -‬احلكــم بفســخ النــكاح ‪ -‬اإلفهــام‬\n      ‫بالعــدة وعــدم الــزواج إال بعــد اخلــروج مــن العــدة واكتســاب احلكــم‬\n                                                                    ‫القطعيــة ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قوله تعالى «فإمساك مبعروف أو تسريح بإحسان»‬\n                             ‫‪ -2‬قوله صلى اهلل عليه وسلم «ال ضرر وال ضرار»‬\n      ‫‪ -3‬مــا روي عــن عمــر رضــى اهلل عنــه «أنــه كتــب يف رجــال غابــوا عــن‬\n                                  ‫نســائهم فأمرهــم بــأن ينفقــوا أو يطلقــوا»‬\n      ‫‪ -4‬قــال يف الشــرح الكبيــر « وان غــاب زوجهــا ولــم يتــرك لهــا نفقــة فــإن‬\n      ‫قــدرت لــه علــى مــال أخــذت بقــدر حاجتهــا حلديــث هنــد وإن لــم تقــدر‬\n                                                                     ‫فلهــا الفســخ» ‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــي بالوكالــة عــن ابنتــه ضــد زوج ابنتــه الغائــب الــذي تعــذر‬\n      ‫تبلغــه ولــم يتــم العثــور عليــه بعــد اإلفــادة الرســمية وقد قــرر ناظر القضية‬\n      ‫ســماع الدعــوى غيابيــا ‪ -‬ادعــى املدعــي وكالــة أن املدعــى عليــه زوج‬\n\n‫‪301‬‬\n\f‫ابنتــه تزوجهــا بالعقــد الصحيــح ولكــن منــذ اكثــر مــن ســنتني تركهــا‬\n‫بــا نفقــه ويعانــى مــن مــرض نفســي وأن ابنتــه تضــررت مــن البقــاء‬\n‫بــدون زوج وال نفقــه وقــد مت البحــث عنــه ولــم يجــد لــه أثــر وطلــب فســخ‬\n‫نكاحهــا منــه ‪ ،‬مت طلــب املدعــى عليــه عــن طريــق األمــارة واإلعــان‬\n‫يف إحــدى الصحــف ‪ ،‬احضــر املدعــي بينــه موصلــه تثبــت صحــة دعــواه‬\n‫وعدلــت شــرعا‪ ،‬قــرر ناظــر القضيــة لألســباب املرصــودة ولقولــه تعالــى‬\n‫«فإمســاك مبعــروف أو تســريح بإحســان» فســخ نــكاح املدعيــة مــن‬\n‫املدعــى عليــه وأفهمهــا بالعــدة الشــرعية وأن ال تتــزوج إال بعــد اكتســاب‬\n‫احلكــم القطعيــة‪ ،‬صــدر قــرار محكمــة االســتئناف مبكــة املكرمــة‬\n                                                   ‫باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33136760‬وتاريــخ‬\n‫‪1433/02/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33330656‬وتاريــخ‬\n‫‪ 1433/02/20‬ه ـ ففــي يــوم الســبت املوافــق ‪ 1433/06/07‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 01 : 28‬وفيهــا حضــر (‪ )........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )........‬بوكالتــه عــن مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة برقــم ‪3396778‬‬\n‫يف ‪1433/06/02‬ه ـ ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه وقــد‬\n‫جــرت منــي ســابق ًا الكتابــة إلمــارة منطقــة مكــة املكرمــة بالكتــاب‬\n‫رقــم ‪ 33/663490‬وتاريــخ ‪1433/4/10‬ه ـ إلبــاغ املدعــى عليــه‬\n\n                                                                                   ‫‪302‬‬\n\f      ‫املذكــور بنــاء علــى املــادة الثامنــة عشــر مــن نظــام املرافعــات الشــرعية‬\n      ‫فوردنــا خطــاب شــعبة التحريــات والبحــث اجلنائــي رقــم ‪ 508435‬يف‬\n      ‫‪1433/05/24‬ه ـ واملتضمــن بأنــه مت البحــث عــن املذكــور ولــم يعثــر‬\n      ‫عليــه وبالرجــوع للنهايــة الطرفيــة اتضــح بــأن عنوانــه منطقــة ‪ ...‬وبســؤال‬\n      ‫املدعــي عــن دعــواه قــال إن املدعــى عليــه زوج ابنتــي تزوجهــا بالعقــد‬\n      ‫الصحيــح بتاريــخ ‪1428/04/01‬ه ـ وقــد تركهــا لــدي بــا نفقــة منــذ‬\n      ‫ســنتني أطلــب إحضــاره واحلكــم البنتــي بالنفقــة وفســخ نكاحهــا منــه‬\n      ‫هــذه دعــواي لــذا فقــد قــررت الكتابــة لرئيــس احملكمــة العامــة‬\n      ‫بالريــاض الســتخالفه أو مــن ينيبــه يف إحضــار املدعــى عليــه وســماع‬\n      ‫مــا لديــه ويف جلســة أخــرى حضــر بوكالتــه عــن ابنتــه املدونــة هويتــه‬\n      ‫ووكالتــه ســلف ًا ولــم يحضــر املدعــى عليــه وال مــن ينيبــه وكنــا ســبق أن‬\n      ‫كتبنــا وخاطبنــا إمــارة منطقــة مكــة بخطابنــا رقــم ‪ 33663490‬وتاريخ‬\n      ‫‪1433/04/10‬ه ـ للبحــث عــن املدعــى عليــه وتبليغــه فوردنــا جواب مدير‬\n      ‫شــعبة التحريــات والبحــث برقــم وتاريــخ ‪1433/05/24‬ه ـ بأنــه بعــد‬\n      ‫البحــث عــن املذكــور لــم يعثــر عليــه وبالرجــوع للنهايــة الطرفيــة أتضــح‬\n      ‫بــأن عنوانــه ‪ ...‬فجــرى منــا الكتابــة لرئيــس احملكمــة العامــة بالريــاض‬\n      ‫بخطابنــا رقــم ‪ 331090182‬وتاريــخ ‪1433/06/10‬ه ـ لتبليــغ املدعــى‬\n      ‫عليــه فوردنــا اجلــواب برقــم بأنــه لــم يعثــر لــه علــى أثــر لــذا فقــد قــررت‬\n      ‫الســير يف الدعــوى غيابي ـ ًا وبســؤال املدعــي عــن دعــواه قــال إن املدعــى‬\n      ‫عليــه زوج ابنتــي بالعقــد الصحيــح عــام ‪1433/4/1‬ه ـ وإنــه منــذ ســنتني‬\n      ‫وأربعــة أشــهر قــد تركهــا لــدي بــا نفقــة ويعانــي مــن مــرض نفســي وقــد‬\n      ‫تضــررت ابنتــي مــن طــول البقــاء دون زوج وال منفــق وقــد حاولــت البحــث‬\n      ‫عنــه بشــتى الســبل ولكنــي لــم أجــد لــه أثــر لــذا أطلــب فســخ نكاحهــا‬\n\n\n‫‪303‬‬\n\f‫منــه هــذه دعــواي وكنــا ســبق أن بحثنــا عــن املدعــى عليــه لتبليغــه عــن‬\n‫الدعــوى ولــم يتــم العثــور عليــه كمــا مت اإلعــان عــن ذلــك يف جريــدة‬\n‫‪ ...‬بعــدد ‪ 17987‬وتاريــخ ‪/3‬رمضــان ‪1433/‬ه ـ بنــاء علــى املــادة ‪18‬‬\n‫مــن نظــام املرافعــات ولــم يراجــع أحــد بهــذا اخلصــوص فقــررت الســير‬\n‫يف الدعــوى ونظرهــا غيابيــا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات‬\n‫ال مــن ســعودي بالســجل‬      ‫وبســؤال املدعــي البينــة أحضــر للشــهادة ك ً‬\n‫املدنــي رقــم و ســعودي بالســجل املدنــي رقــم وبســؤالهما عمــا لديهمــا مــن‬\n‫ا أشــهد بــاهلل العظيــم بأننــا‬‫شــهد كل واحــد منهمــا علــى انفــراد قائ ـ ً‬\n‫نعــرف املدعــي وكالــة وأن ابنتــه عنــده منــذ أكثــر مــن ســنتني وزوجهــا‬\n‫غائــب عنهــا منــذ اكثــر مــن ســنتني ونحــن جيــران لهــم هكــذا شــهد‬\n‫وعــدال مــن ســعودي بالســجل املدنــي رقــم و ســعودي بالســجل املدنــي‬\n‫رقــم ويف جلســة أخــرى حضــر املدونــة هويتــه ســلف ًا وحضــرت املدعيــة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬  ‫ســعودية بالســجل املدنــي رقــم فبنـ ً‬\n‫ومــا شــهدت بــه البينــة مــن غيــاب زوج املدعيــة أكثــر مــن ســنتني وحيــث‬\n‫جــرى البحــث عنــه واإلعــان يف جريــدة املدينــة إلبالغــه إال أنــه لــم‬\n‫يتقــدم أحــد للمحكمــة ولتضــرر املدعيــة مــن ذلــك حيــث أنهــا معلقــة‬\n‫عنــد والدهــا ولــم ينفــق عليهــا زوجهــا ولــم يتــرك لهــا نفقــة وملــا روي عــن‬\n‫عمــر أنــه كتــب يف رجــال غابــوا عــن نســائهم فأمرهــم بــأن ينفقــوا أو‬\n‫يطلقــوا قــال يف الشــرح الكبيــر «وإن غــاب زوجهــا ولــم يتــرك لهــا نفقــة‬\n‫فــإن قــدرت لــه علــى مــال أخــذت بقــدر حاجتهــا حلديــث هنــد وإن لــم‬\n‫تقــدر فلهــا الفســخ « ولقــول الرســول صلــى اهلل عليــه وســلم «ال ضــرر‬\n‫وال ضــرار « ولقولــه تعالــى (فإمســاك مبعــروف أو تســريح بإحســان)‬\n‫لذلــك كلــه فقــد فســخت نــكاح املدعيــة مــن زوجهــا وأفهمــت املدعيــة‬\n\n\n                                                                                        ‫‪304‬‬\n\f      ‫بــأن عليهــا العــدة حيضــة وأحــدة يف أصــح قولــي العلمــاء وأن ال تتــزوج‬\n      ‫حتــى يصــدق احلكــم مــن محكمــة االســتئناف ولتعــذر تســليم نســخة‬\n      ‫احلكــم للمدعــى عليــه ســيتم رفعــه لالســتئناف لتدقيقــه وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪1434/01/06‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا حاكــم القضيــة يف هــذا اليــوم الســبت‬\n      ‫املوافــق ‪1434/4/13‬ه ـ عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n      ‫‪ 34626831‬يف ‪1434/4/7‬ه ـ وبرفقهــا قــرار الدائــرة الثالثــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال رقــم ‪3463023‬‬\n      ‫يف ‪1434/3/16‬ه ـ املتضمــن مــا نصــه « وبدراســة الصــك وصورة ضبطه‬\n      ‫تقــررت املوافقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم « أه ـ قاضــي اســتئناف ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه وحتــى‬\n      ‫ال يخفــى جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                               ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/4/13‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34433921‬وتاريــخ ‪3/4‬‬\n      ‫‪1434/‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪)000( /‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 344668‬وتاريــخ‬\n      ‫‪1434/1/6‬ه ـ املتضمــن طلــب املــرأة فســخ نكاحهــا مــن زوجهــا الغائــب‬\n\n\n‫‪305‬‬\n\f‫عــن مجلــس احلكــم ‪ ،‬وبدراســة الصــك وصــورة ضبطــه تقــررت املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                              ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":301,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"31afde800a2e501602c8ef7b592bf4406088222a787effa726b0aee904304d86","normalized_text_hash":"912efedf801face581b76853f6387ba7973d1cdbb09b78b4ec8275fee9583963","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p301-344668"}]$archive_payload$::jsonb) AS x LIMIT 25
